window.GQ = [{"title": "Leetcode 2475. Number of Unequal Triplets in Array", "level": "Mid-level", "reports": 16, "last": "Mid January, 2025", "desc": "Count the number of index triplets (i<j<k) in an array whose three values are pairwise distinct. With n ≤ 100 this reduces to combinatorially counting distinct-value triples (e.g., via frequency counts) rather than heavy algorithms.", "page": 2, "cat": "array", "lc": 2475, "en": "LC 2475. Number of Unequal Triplets in Array", "cn": "数组中不等三元组数", "id": "lc2475", "sol": {"ap": "按值频率分组,O(n)中间值扫描:当前值作中间,左×当前×右。", "code": "from collections import Counter\nclass Solution:\n    def unequalTriplets(self, nums):\n        cnt = Counter(nums); res = 0; left = 0; right = len(nums)\n        for v, c in cnt.items():\n            right -= c\n            res += left * c * right\n            left += c\n        return res", "t": "O(n)", "s": "O(n)", "fu": "暴力O(n³)也能过(n<=100)。好三元组(#1534)是差值约束。"}}, {"title": "Leetcode 56. Merge Intervals", "level": "Mid-level-Staff", "reports": 13, "last": "Late May, 2026", "desc": "Given a list of intervals, merge all overlapping (including touching endpoints) intervals and return the minimal set of non-overlapping intervals that cover them. Key pattern: sort by start and sweep/merge adjacent ranges whose starts are <= current end.", "page": 1, "cat": "intervals", "lc": 56, "en": "LC 56. Merge Intervals", "cn": "合并区间", "id": "lc56", "sol": {"ap": "排序+扫描:重叠则延伸末端,否则新开一段。", "code": "class Solution:\n    def merge(self, intervals):\n        intervals.sort(key=lambda x: x[0])\n        res = []\n        for s, e in intervals:\n            if not res or res[-1][1] < s:\n                res.append([s, e])\n            else:\n                res[-1][1] = max(res[-1][1], e)\n        return res", "t": "O(n log n)", "s": "O(n)", "fu": "① 插入单个区间(#57):不排序线性扫。② 区间是否有公共交集:max(start)<=min(end)。③ 删除被覆盖区间(#1288)。"}}, {"title": "Count Islands in Binary Trees", "level": "Intern, Mid-level", "reports": 10, "last": "Early December, 2025", "desc": "Given a binary tree where nodes have values (typically 0 or 1), analyze the 'islands' (connected components of similar values) within the tree. Tasks include counting the total number of islands, identifying unique island types based on their structure and size, and analyzing different patterns of island formations. An island is defined as a connected group of nodes with the same value.", "page": 1, "cat": "tree", "lc": null, "en": "Count Islands in Binary Trees", "cn": "二叉树中的岛屿计数", "id": "count-islands-in-binary-trees", "sol": null}, {"title": "Leetcode 704. Binary Search", "level": "Intern-Mid-level", "reports": 5, "last": "Late October, 2024", "desc": "Given a sorted (ascending) array of unique integers and a target value, return the index of the target or -1 if not present; the solution must run in O(log n) time (i.e., implement binary search).", "page": 4, "cat": "binary-search", "lc": 704, "en": "LC 704. Binary Search", "cn": "二分查找", "id": "lc704", "sol": {"ap": "闭区间lo<=hi模板,两边都±1。", "code": "class Solution:\n    def search(self, nums, target):\n        lo, hi = 0, len(nums) - 1\n        while lo <= hi:\n            mid = (lo + hi) // 2\n            if nums[mid] == target: return mid\n            elif nums[mid] < target: lo = mid + 1\n            else: hi = mid - 1\n        return -1", "t": "O(log n)", "s": "O(1)", "fu": "找左右边界(#34)→ lower_bound;旋转数组(#33)→ 判哪半有序。"}}, {"title": "Leetcode 359. Logger Rate Limiter", "level": "Junior-Senior", "reports": 4, "last": "Mid May, 2026", "desc": "Implement a logger that decides whether to print a message at a given timestamp: return true if the message hasn't been printed in the last 10 seconds, otherwise false. This requires tracking each message's last printed time (e.g., with a map) to enforce the fixed time window efficiently.", "page": 1, "cat": "design", "lc": 359, "en": "LC 359. Logger Rate Limiter", "cn": "日志速率限制器", "id": "lc359", "sol": {"ap": "哈希表存每条消息上次打印时间;>=10秒才打印并更新。", "code": "class Logger:\n    def __init__(self):\n        self.last = {}\n    def shouldPrintMessage(self, timestamp, message):\n        if message not in self.last or timestamp - self.last[message] >= 10:\n            self.last[message] = timestamp\n            return True\n        return False", "t": "O(1)", "s": "O(M)", "fu": "① 内存无限增长 → deque 懒清理过期。② 分布式 → Redis SET key EX 10 NX。③ 多线程 → 加锁。"}}, {"title": "Leetcode 806. Number of Lines To Write String", "level": "Junior-Mid-level", "reports": 4, "last": "Mid March, 2026", "desc": "Given an array widths mapping each lowercase letter to its pixel width and a string s, pack characters sequentially into lines with a maximum width of 100 pixels and return [number_of_lines, width_of_last_line]. This is solved by greedily scanning s, accumulating letter widths and starting a new line whenever adding the next letter would exceed 100.", "page": 1, "cat": "string", "lc": 806, "en": "LC 806. Number of Lines To Write String", "cn": "写字符串需要的行数", "id": "lc806", "sol": {"ap": "逐字符累加宽度,超100换行。", "code": "class Solution:\n    def numberOfLines(self, widths, s):\n        lines, cur = 1, 0\n        for ch in s:\n            w = widths[ord(ch) - ord('a')]\n            if cur + w > 100: lines += 1; cur = w\n            else: cur += w\n        return [lines, cur]", "t": "O(n)", "s": "O(1)", "fu": ""}}, {"title": "Car Rental Optimization", "level": "Senior", "reports": 4, "last": "Early March, 2026", "desc": "Given N cars and a list of rental requests (each with pickup time, return time, and ID), assign cars to requests using the minimum number of cars possible. Return a list of car assignments for each request ID.", "page": 1, "cat": "intervals", "lc": null, "en": "Car Rental Optimization", "cn": "租车优化", "id": "car-rental-optimization", "sol": null}, {"title": "File System Size Analysis and Reporting", "level": "Intern-Mid-level", "reports": 4, "last": "Early January, 2026", "desc": "Implement functionality to analyze and report file system sizes. This includes calculating sizes of individual entities (files/folders), finding the largest files in a directory, and determining the largest folders based on their immediate file contents. The solution should handle large directory structures efficiently.", "page": 1, "cat": "design", "lc": null, "en": "File System Size Analysis and Reporting", "cn": "文件系统大小分析", "id": "file-system-size-analysis-and-reporting", "sol": null}, {"title": "Leetcode 755. Pour Water", "level": "Mid-level", "reports": 4, "last": "Mid December, 2024", "desc": "Given an array of terrain heights, V droplets are poured one by one at index K and each droplet greedily rolls to the leftmost lowest reachable position (otherwise to the right) before settling; return the final heights after all drops. The core challenge is correctly simulating these local greedy flows (left-then-right scan) and updating heights efficiently.", "page": 2, "cat": "array", "lc": 755, "en": "LC 755. Pour Water", "cn": "Leetcode 755. Pour Water", "id": "lc755", "sol": null}, {"title": "Leetcode 460. LFU Cache", "level": "Junior-Senior", "reports": 3, "last": "Late March, 2026", "desc": "Implement an LFU cache with O(1) average-time get and put operations that evicts the least-frequently-used key when capacity is exceeded, breaking ties by least-recently-used. The cache must update a key's frequency (and recency) on both get and put, and support inserting and updating values.", "page": 1, "cat": "design", "lc": 460, "en": "LC 460. LFU Cache", "cn": "LFU缓存", "id": "lc460", "sol": {"ap": "三件套(val/freq/freq->keys)+min_freq主动维护+OrderedDict当LRU平局。", "code": "from collections import OrderedDict, defaultdict\nclass LFUCache:\n    def __init__(self, capacity):\n        self.cap = capacity; self.min_freq = 0\n        self.key_to_val = {}; self.key_to_freq = {}\n        self.freq_to_keys = defaultdict(OrderedDict)\n    def _touch(self, key):\n        f = self.key_to_freq[key]\n        del self.freq_to_keys[f][key]\n        if not self.freq_to_keys[f] and f == self.min_freq:\n            self.min_freq += 1\n        self.key_to_freq[key] = f+1\n        self.freq_to_keys[f+1][key] = None\n    def get(self, key):\n        if key not in self.key_to_val: return -1\n        self._touch(key); return self.key_to_val[key]\n    def put(self, key, value):\n        if self.cap == 0: return\n        if key in self.key_to_val:\n            self.key_to_val[key] = value; self._touch(key); return\n        if len(self.key_to_val) >= self.cap:\n            ev,_ = self.freq_to_keys[self.min_freq].popitem(last=False)\n            del self.key_to_val[ev]; del self.key_to_freq[ev]\n        self.key_to_val[key] = value; self.key_to_freq[key] = 1\n        self.freq_to_keys[1][key] = None; self.min_freq = 1", "t": "get/put O(1)", "s": "O(capacity)", "fu": "① LRU(#146)更简单,OrderedDict。② 带 TTL → 惰性删除。③ 并发 → 分段锁。"}}, {"title": "Knapsack Problem Variations", "level": "Mid-level-Senior", "reports": 3, "last": "Early March, 2026", "desc": "Solve variations of the classic 0/1 knapsack problem, such as when profits are binary (1 or 2) or when weights are fractional (up to 2 decimal places) but items cannot be partially selected. Apply dynamic programming techniques while handling the specific constraints of each variation.", "page": 1, "cat": "dp", "lc": null, "en": "Knapsack Problem Variations", "cn": "背包问题变体", "id": "knapsack-problem-variations", "sol": null}, {"title": "Leetcode 1254. Number of Closed Islands", "level": "Senior-Staff, Manager", "reports": 3, "last": "Late January, 2026", "desc": "Count the number of 4-directionally connected components of 0s in a binary grid that are completely surrounded by 1s (i.e., the component does not touch the grid boundary). This is a flood-fill/DFS-BFS style problem on an up to 100x100 grid.", "page": 1, "cat": "dfs", "lc": 1254, "en": "LC 1254. Number of Closed Islands", "cn": "统计封闭岛屿", "id": "lc1254", "sol": {"ap": "0=陆地;DFS整岛,碰边界则is_closed=False(全称flag,不提前return)。", "code": "class Solution:\n    def closedIsland(self, grid):\n        m, n = len(grid), len(grid[0]); seen = set(); is_closed = True\n        def dfs(i, j):\n            nonlocal is_closed\n            if i<0 or i>=m or j<0 or j>=n or grid[i][j]==1 or (i,j) in seen: return\n            seen.add((i,j))\n            if i==0 or i==m-1 or j==0 or j==n-1: is_closed = False\n            for dx,dy in [(0,1),(0,-1),(1,0),(-1,0)]: dfs(i+dx, j+dy)\n        count = 0\n        for i in range(m):\n            for j in range(n):\n                if grid[i][j]==0 and (i,j) not in seen:\n                    is_closed = True; dfs(i,j)\n                    if is_closed: count += 1\n        return count", "t": "O(m·n)", "s": "O(m·n)", "fu": "先从边界DFS淹掉触边岛,再数剩下的。"}}, {"title": "Leetcode 2402. Meeting Rooms III", "level": "Mid-level-Senior", "reports": 3, "last": "Late November, 2025", "desc": "Assign each meeting (with unique start times) to the lowest-numbered available room or delay it (keeping its duration and prioritizing earlier original start times) until a room frees, and return the index of the room that hosted the most meetings. The core challenge is simulating this scheduling efficiently using priority queues to track free room indices and next-free times while counting assignments.", "page": 1, "cat": "intervals", "lc": 2402, "en": "LC 2402. Meeting Rooms III", "cn": "会议室III", "id": "lc2402", "sol": {"ap": "双堆:idle 存空房号,busy 存(end,房号);没空房则等最早结束的并延后。", "code": "import heapq\nclass Solution:\n    def mostBooked(self, n, meetings):\n        meetings.sort()\n        idle = list(range(n)); heapq.heapify(idle)\n        busy = []; count = [0]*n\n        for s, e in meetings:\n            while busy and busy[0][0] <= s:\n                _, r = heapq.heappop(busy); heapq.heappush(idle, r)\n            if idle:\n                r = heapq.heappop(idle); heapq.heappush(busy, (e, r))\n            else:\n                end, r = heapq.heappop(busy)\n                heapq.heappush(busy, (end + (e - s), r))\n            count[r] += 1\n        return count.index(max(count))", "t": "O(m log m + m log n)", "s": "O(n)", "fu": "延后保持时长不变;若问被举办总时长最长的房间,count 累加时长。"}}, {"title": "Leetcode 1197. Minimum Knight Moves", "level": "Mid-level-Senior", "reports": 3, "last": "Late November, 2025", "desc": "Given target coordinates (x, y), find the minimum number of knight moves required to reach that square from (0,0) on an infinite chessboard. This is a shortest-path problem on an implicit unweighted grid graph (solveable with BFS/bi‑directional BFS or A*), often simplified by exploiting symmetry to the first quadrant.", "page": 1, "cat": "bfs", "lc": 1197, "en": "LC 1197. Minimum Knight Moves", "cn": "最小跳跃骑士", "id": "lc1197", "sol": {"ap": "无权图BFS求最短步数;骑士8方向;对称到第一象限剪枝。", "code": "from collections import deque\nclass Solution:\n    def minKnightMoves(self, x, y):\n        x, y = abs(x), abs(y)\n        moves = [(1,2),(2,1),(-1,2),(-2,1),(1,-2),(2,-1),(-1,-2),(-2,-1)]\n        q = deque([(0,0,0)]); seen = {(0,0)}\n        while q:\n            cx, cy, d = q.popleft()\n            if (cx, cy) == (x, y): return d\n            for dx, dy in moves:\n                nx, ny = cx+dx, cy+dy\n                if (nx,ny) not in seen and -2 <= nx and -2 <= ny:\n                    seen.add((nx,ny)); q.append((nx, ny, d+1))\n        return -1", "t": "O(max(x,y)²)", "s": "O(max(x,y)²)", "fu": "棋盘无限 → 对称+剪枝;或数学公式O(1)。"}}, {"title": "Leetcode 2445. Number of Nodes With Value One", "level": "Mid-level", "reports": 3, "last": "Mid January, 2025", "desc": "Given a tree (or graph) whose nodes are labeled 0 or 1 and a set of rules/operations that change node values based on ancestors or path flips, determine how many nodes end up with value 1. This typically requires a DFS/BFS that carries a cumulative flip/XOR state (or other propagated state) and careful bookkeeping to apply updates efficiently.", "page": 2, "cat": "array", "lc": 2445, "en": "LC 2445. Number of Nodes With Value One", "cn": "值为1的节点数", "id": "lc2445", "sol": null}, {"title": "Convert Graph to Binary Tree with Alternating Colors", "level": "Intern, Mid-level", "reports": 3, "last": "Early January, 2025", "desc": "Given an undirected connected acyclic graph where each node has at most 3 edges, and nodes are colored (either Black/White or Red/Black), find a root vertex such that when the graph is suspended from that vertex, it becomes a binary tree where all nodes at the same level have the same color, and adjacent levels have different colors. Return -1 if no such vertex exists.", "page": 3, "cat": "bfs", "lc": null, "en": "Convert Graph to Binary Tree with Alternating Colors", "cn": "图转交替色二叉树", "id": "convert-graph-to-binary-tree-with-altern", "sol": null}, {"title": "Find Root Node in Colored Tree with Pattern Constraints", "level": "Mid-level", "reports": 3, "last": "Early January, 2025", "desc": "Given an undirected connected acyclic graph where each node has at most 3 edges and nodes are colored (Red/Black/White or similar color patterns), find a root node such that when the graph is viewed as a binary tree from that root, it satisfies specific color pattern constraints across levels (e.g., RBWRBW repeating pattern or alternating colors). Return -1 if no valid root exists.", "page": 3, "cat": "bfs", "lc": null, "en": "Find Root Node in Colored Tree with Pattern Constraints", "cn": "按模式约束找彩色树根", "id": "find-root-node-in-colored-tree-with-patt", "sol": null}, {"title": "Leetcode 1534. Count Good Triplets", "level": "Mid-level", "reports": 3, "last": "Late December, 2024", "desc": "Count the number of index triplets (i < j < k) in arr such that the pairwise absolute differences satisfy |arr[i]-arr[j]| ≤ a, |arr[j]-arr[k]| ≤ b, and |arr[i]-arr[k]| ≤ c. With arr.length ≤ 100, the constraints make a direct check over all triplets efficient.", "page": 3, "cat": "array", "lc": 1534, "en": "LC 1534. Count Good Triplets", "cn": "统计好三元组", "id": "lc1534", "sol": {"ap": "n<=100,O(n²)枚举i,j提前剪枝再枚举k。", "code": "class Solution:\n    def countGoodTriplets(self, arr, a, b, c):\n        n = len(arr); count = 0\n        for i in range(n):\n            for j in range(i+1, n):\n                if abs(arr[i]-arr[j]) > a: continue\n                for k in range(j+1, n):\n                    if abs(arr[j]-arr[k]) <= b and abs(arr[i]-arr[k]) <= c:\n                        count += 1\n        return count", "t": "O(n³)", "s": "O(1)", "fu": "优化到O(n²)→ 固定(i,j)后前缀计数找k。"}}, {"title": "Leetcode 296. Best Meeting Point", "level": "Mid-level", "reports": 3, "last": "Mid October, 2024", "desc": "Given a grid of homes (1s) find a meeting cell that minimizes the total Manhattan distance from all homes. Key insight: Manhattan distance is separable by rows and columns, so reduce to two 1D problems and choose the median row and median column to minimize total distance.", "page": 4, "cat": "array", "lc": 296, "en": "LC 296. Best Meeting Point", "cn": "最佳会议点", "id": "lc296", "sol": {"ap": "曼哈顿距离行列独立;一维最优点=中位数,双指针求距离和。", "code": "class Solution:\n    def minTotalDistance(self, grid):\n        m, n = len(grid), len(grid[0])\n        rows = [i for i in range(m) for j in range(n) if grid[i][j]==1]\n        cols = [j for j in range(n) for i in range(m) if grid[i][j]==1]\n        def dist(pts):\n            lo, hi, d = 0, len(pts)-1, 0\n            while lo < hi:\n                d += pts[hi] - pts[lo]; lo += 1; hi -= 1\n            return d\n        return dist(rows) + dist(cols)", "t": "O(m·n)", "s": "O(m·n)", "fu": "绝对距离和→中位数;平方和→平均数。"}}, {"title": "Leetcode 3169. Count Days Without Meetings", "level": "Mid-level", "reports": 3, "last": "Early September, 2024", "desc": "Given a total number of days and a list of meeting intervals, return how many days in [1, days] are not covered by any meeting — effectively days minus the total length of the union of possibly overlapping intervals. Note meetings may overlap and days can be up to 1e9, so treat it as an interval-merging / sweep-line problem rather than per-day marking.", "page": 5, "cat": "intervals", "lc": 3169, "en": "LC 3169. Count Days Without Meetings", "cn": "无会议的天数", "id": "lc3169", "sol": {"ap": "排序+prev_end 扫描,缝隙即空闲;别忘开头结尾。", "code": "class Solution:\n    def countDays(self, days, meetings):\n        meetings.sort(key=lambda x: x[0])\n        free, prev_end = 0, 0\n        for s, e in meetings:\n            if s > prev_end + 1:\n                free += s - prev_end - 1\n            prev_end = max(prev_end, e)\n        if days > prev_end:\n            free += days - prev_end\n        return free", "t": "O(n log n)", "s": "O(1)", "fu": "求最长连续空闲段 → 记录最大缝隙。"}}, {"title": "Leetcode 347. Top K Frequent Elements", "level": "Mid-level-Senior", "reports": 2, "last": "Late April, 2026", "desc": "Given an integer array and k, return the k most frequent elements — the core challenge is to count element frequencies and extract the top-k efficiently (better than O(n log n)), typically using a frequency map combined with a min-heap (O(n log k)) or bucket sort (O(n)).", "page": 1, "cat": "heap", "lc": 347, "en": "LC 347. Top K Frequent Elements", "cn": "前K高频元素", "id": "lc347", "sol": {"ap": "Counter+桶排序(索引=频率),从高频往低取k个。", "code": "from collections import Counter\nclass Solution:\n    def topKFrequent(self, nums, k):\n        cnt = Counter(nums); n = len(nums)\n        buckets = [[] for _ in range(n+1)]\n        for num, f in cnt.items(): buckets[f].append(num)\n        res = []\n        for i in range(n, 0, -1):\n            for num in buckets[i]:\n                res.append(num)\n                if len(res) == k: return res\n        return res", "t": "O(n)", "s": "O(n)", "fu": "数据流 → 小顶堆size k,O(n log k)。"}}, {"title": "Leetcode 489. Robot Room Cleaner", "level": "Mid-level", "reports": 2, "last": "Mid March, 2026", "desc": "Control a robot with only move/turn/clean APIs to traverse and clean every reachable cell in an unknown grid with obstacles and no global map. The challenge is to explore the entire accessible area using DFS/backtracking while tracking visited coordinates and managing orientation to avoid revisiting or getting stuck.", "page": 1, "cat": "dfs", "lc": 489, "en": "LC 489. Robot Room Cleaner", "cn": "扫地机器人", "id": "lc489", "sol": {"ap": "相对坐标(0,0);方向顺时针配turnRight;go_back物理复位;循环末尾turnRight同步朝向。", "code": "class Solution:\n    def cleanRoom(self, robot):\n        dirs = [(-1,0),(0,1),(1,0),(0,-1)]; visited = set()\n        def go_back():\n            robot.turnRight(); robot.turnRight(); robot.move()\n            robot.turnRight(); robot.turnRight()\n        def bt(r, c, d):\n            visited.add((r,c)); robot.clean()\n            for i in range(4):\n                nd = (d+i) % 4; dx, dy = dirs[nd]\n                nr, nc = r+dx, c+dy\n                if (nr,nc) not in visited and robot.move():\n                    bt(nr, nc, nd); go_back()\n                robot.turnRight()\n        bt(0, 0, 0)", "t": "O(N-M)", "s": "O(N-M)", "fu": "没有现成网格 → 相对坐标+物理回溯。L5经典puzzle。"}}, {"title": "Leetcode 913. Cat and Mouse", "level": "Mid-level, Staff", "reports": 2, "last": "Early January, 2026", "desc": "Two players alternate moves along edges of an undirected graph: the mouse starts at 1, the cat at 2 (cat cannot enter node 0), and the game ends if the mouse reaches hole 0 (mouse wins), the cat lands on the mouse (cat wins), or a position repeats (draw). Determine which of the three outcomes occurs under optimal play — essentially resolving a finite game-state graph (mouse, cat, turn) with cycles/draws via retrograde analysis/BFS.", "page": 1, "cat": "bfs", "lc": 913, "en": "LC 913. Cat and Mouse", "cn": "猫和老鼠", "id": "lc913", "sol": null}, {"title": "Leetcode 642. Design Search Autocomplete System", "level": "Mid-level-Senior", "reports": 2, "last": "Early November, 2025", "desc": "Design an online autocomplete system that processes characters one-by-one, returning the top 3 historically most frequent sentences that match the current prefix (ranked by frequency, then lexicographically), and inserts new sentences when the special character '#' is entered. The core challenge is supporting fast prefix queries and incremental updates over sentence frequencies, typically requiring a prefix-indexed structure (e.g., trie) or efficient top-k maintenance per prefix.", "page": 1, "cat": "design", "lc": 642, "en": "LC 642. Design Search Autocomplete System", "cn": "设计自动补全系统", "id": "lc642", "sol": {"ap": "Trie每节点存「经过它的句子->频率」;输入前缀走到节点取top3。", "code": "import collections\nclass TrieNode:\n    def __init__(self):\n        self.children = {}\n        self.counts = collections.defaultdict(int)\nclass AutocompleteSystem:\n    def __init__(self, sentences, times):\n        self.root = TrieNode(); self.keyword = \"\"\n        for s, t in zip(sentences, times):\n            self._add(s, t)\n    def _add(self, sentence, count):\n        node = self.root\n        for ch in sentence:\n            node = node.children.setdefault(ch, TrieNode())\n            node.counts[sentence] += count\n    def input(self, c):\n        if c == '#':\n            self._add(self.keyword, 1); self.keyword = \"\"; return []\n        self.keyword += c\n        node = self.root\n        for ch in self.keyword:\n            if ch not in node.children: return []\n            node = node.children[ch]\n        return sorted(node.counts, key=lambda s: (-node.counts[s], s))[:3]", "t": "input O(p+k log k)", "s": "O(总字符×句子)", "fu": "句子量极大 → 每节点维护 top3 堆而非全量。"}}, {"title": "Leetcode 269. Alien Dictionary", "level": "Staff", "reports": 2, "last": "Mid October, 2025", "desc": "Given a sorted list of words in an unknown alphabet, infer the relative ordering of characters by deriving precedence constraints between first differing letters, then produce a valid topological ordering of the resulting directed graph or detect that no valid order exists (cycle or invalid prefix).", "page": 2, "cat": "bfs", "lc": 269, "en": "LC 269. Alien Dictionary", "cn": "火星词典", "id": "lc269", "sol": {"ap": "相邻单词第一个不同字符给顺序边→拓扑排序。前缀关系判非法。", "code": "from collections import defaultdict, deque\nclass Solution:\n    def alienOrder(self, words):\n        chars = set(''.join(words))\n        graph = defaultdict(set); indeg = {c:0 for c in chars}\n        for i in range(len(words)-1):\n            w1, w2 = words[i], words[i+1]\n            found = False\n            for a, b in zip(w1, w2):\n                if a != b:\n                    if b not in graph[a]:\n                        graph[a].add(b); indeg[b] += 1\n                    found = True; break\n            if not found and len(w1) > len(w2): return \"\"\n        q = deque(c for c in chars if indeg[c]==0); res = []\n        while q:\n            c = q.popleft(); res.append(c)\n            for nxt in graph[c]:\n                indeg[nxt] -= 1\n                if indeg[nxt]==0: q.append(nxt)\n        return ''.join(res) if len(res)==len(chars) else \"\"    # 有环→空", "t": "O(总字符)", "s": "O(1)", "fu": "序列重建(#444):判拓扑序是否唯一。"}}, {"title": "Leetcode 212. Word Search II", "level": "Intern, Mid-level", "reports": 2, "last": "Mid October, 2025", "desc": "Given an m×n letter grid and a list of words, find all words that can be formed by sequentially adjacent (horizontal/vertical) non-repeating cells. The core challenge is efficiently searching many candidate words on the board using DFS/backtracking with prefix pruning (e.g., a Trie) to handle up to 12×12 boards and tens of thousands of words.", "page": 2, "cat": "dfs", "lc": 212, "en": "LC 212. Word Search II", "cn": "单词搜索II", "id": "lc212", "sol": {"ap": "所有词建Trie,只扫一遍board,沿Trie走+剪枝,找到删'#'防重复。", "code": "class Solution:\n    def findWords(self, board, words):\n        trie = {}\n        for w in words:\n            node = trie\n            for ch in w: node = node.setdefault(ch, {})\n            node['#'] = w\n        m, n = len(board), len(board[0]); res = []\n        def dfs(i, j, node):\n            ch = board[i][j]\n            if ch not in node: return\n            nxt = node[ch]\n            if '#' in nxt: res.append(nxt['#']); del nxt['#']\n            board[i][j] = '#'\n            for di,dj in [(0,1),(0,-1),(1,0),(-1,0)]:\n                ni, nj = i+di, j+dj\n                if 0<=ni<m and 0<=nj<n and board[ni][nj]!='#':\n                    dfs(ni, nj, nxt)\n            board[i][j] = ch\n        for i in range(m):\n            for j in range(n): dfs(i, j, trie)\n        return res", "t": "O(m·n·3^L)", "s": "O(总字符)", "fu": "词典极大 → Trie比逐词DFS快。"}}, {"title": "Leetcode 253. Meeting Rooms II", "level": "Mid-level-Senior", "reports": 2, "last": "Early October, 2025", "desc": "Given a list of meeting time intervals, determine the minimum number of conference rooms required so that no meetings overlap. The core challenge is computing the maximum number of concurrent intervals (e.g., via sorting with a min-heap of end times or a sweep-line of start/end events).", "page": 2, "cat": "intervals", "lc": 253, "en": "LC 253. Meeting Rooms II", "cn": "会议室II", "id": "lc253", "sol": {"ap": "按 start 排序,最小堆存进行中会议的 end;堆顶<=当前start则复用。堆大小=房间数。", "code": "import heapq\nclass Solution:\n    def minMeetingRooms(self, intervals):\n        intervals.sort(key=lambda x: x[0])\n        heap = []\n        for s, e in intervals:\n            if heap and heap[0] <= s:\n                heapq.heappop(heap)\n            heapq.heappush(heap, e)\n        return len(heap)", "t": "O(n log n)", "s": "O(n)", "fu": "① 返回每会议房号 → 堆存(end,room)。② 房间有限求最多会议(#2402)→ 双堆+延后。③ 扫描线:事件+1/-1。"}}, {"title": "Remove Bad Pairs from a String", "level": "Mid-level", "reports": 2, "last": "Mid January, 2025", "desc": "Remove bad pairs from a string. A bad pair is defined as adjacent characters that are the same letter in different cases (e.g., 'xX'). Implement a solution to remove these bad pairs.", "page": 2, "cat": "string", "lc": null, "en": "Remove Bad Pairs from a String", "cn": "删除字符串中的坏对", "id": "remove-bad-pairs-from-a-string", "sol": null}, {"title": "Leetcode 346. Moving Average from Data Stream", "level": "Mid-level", "reports": 2, "last": "Late January, 2025", "desc": "Design a data structure that, given a continuous stream of numbers and a fixed window size k, returns the moving average of the last k values each time a new value arrives. The challenge is to maintain the sliding window efficiently (constant-time update and query) while using only O(k) space.", "page": 2, "cat": "design", "lc": 346, "en": "LC 346. Moving Average from Data Stream", "cn": "数据流移动平均", "id": "lc346", "sol": {"ap": "deque维护窗口+增量sum,避免重算。", "code": "from collections import deque\nclass MovingAverage:\n    def __init__(self, size):\n        self.size = size; self.q = deque(); self.sum = 0\n    def next(self, val):\n        self.q.append(val); self.sum += val\n        if len(self.q) > self.size:\n            self.sum -= self.q.popleft()\n        return self.sum / len(self.q)", "t": "next O(1)", "s": "O(size)", "fu": "窗口中位数 → 双堆(#480);窗口最大值 → 单调队列。"}}, {"title": "Problem About Interns and Flats Using a Greedy Approach", "level": "Junior", "reports": 2, "last": "Late January, 2025", "desc": "This problem involves assigning interns to flats using a greedy algorithm. The goal is to optimize the allocation based on certain criteria, such as minimizing the distance between interns and their assigned flats or maximizing the satisfaction of the interns with their assignments. The problem requires a strategic approach to ensure the best possible outcome given the constraints.", "page": 2, "cat": "intervals", "lc": null, "en": "Problem About Interns and Flats Using a Greedy Approach", "cn": "实习生与公寓贪心", "id": "problem-about-interns-and-flats-using-a-", "sol": null}, {"title": "Leetcode 1825. Finding MK Average", "level": "Mid-level", "reports": 2, "last": "Mid January, 2025", "desc": "Maintain a sliding window of the last m stream elements and, after discarding the smallest k and largest k values, return the integer average of the remaining elements (return -1 if fewer than m elements). The core challenge is to support addElement and calculateMKAverage efficiently by keeping ordered partitions and their sums (e.g., via balanced BSTs/multisets or heaps with counts).", "page": 2, "cat": "design", "lc": 1825, "en": "LC 1825. Finding MK Average", "cn": "MK平均值", "id": "lc1825", "sol": {"ap": "三段桶(SortedList):low/mid/high 各维护sum;查询返回 mid_sum/(m-2k)。", "code": "from collections import deque\nfrom sortedcontainers import SortedList\nclass MKAverage:\n    def __init__(self, m, k):\n        self.m, self.k = m, k\n        self.q = deque()\n        self.low = SortedList(); self.mid = SortedList(); self.high = SortedList()\n        self.low_sum = self.mid_sum = self.high_sum = 0\n    def addElement(self, num):\n        self.q.append(num); self._add(num)\n        if len(self.q) > self.m:\n            self._remove(self.q.popleft())\n    def _add(self, x):\n        self.low.add(x); self.low_sum += x\n        if len(self.low) > self.k:\n            v = self.low.pop(); self.low_sum -= v\n            self.mid.add(v); self.mid_sum += v\n        if len(self.mid) > self.m - 2*self.k:\n            v = self.mid.pop(); self.mid_sum -= v\n            self.high.add(v); self.high_sum += v\n    def _remove(self, x):\n        if x <= self.low[-1]:\n            self.low.remove(x); self.low_sum -= x\n            if self.mid:\n                v = self.mid.pop(0); self.mid_sum -= v; self.low.add(v); self.low_sum += v\n        elif x >= self.high[0]:\n            self.high.remove(x); self.high_sum -= x\n            if self.mid:\n                v = self.mid.pop(); self.mid_sum -= v; self.high.add(v); self.high_sum += v\n        else:\n            self.mid.remove(x); self.mid_sum -= x\n    def calculateMKAverage(self):\n        if len(self.q) < self.m: return -1\n        return self.mid_sum // (self.m - 2*self.k)", "t": "add O(log m) · query O(1)", "s": "O(m)", "fu": "不用 SortedList → 两个堆+懒删除,更复杂。"}}, {"title": "Song Shuffler", "level": "Junior-Mid-level", "reports": 2, "last": "Early January, 2025", "desc": "Design an algorithm to shuffle a playlist of songs such that each song is played once in a random order. The algorithm should ensure that the shuffle is unbiased and each permutation of the playlist is equally likely.", "page": 2, "cat": "design", "lc": null, "en": "Song Shuffler", "cn": "歌曲随机播放器", "id": "song-shuffler", "sol": null}, {"title": "Leetcode 2162. Minimum Cost to Set Cooking Time", "level": "Mid-level", "reports": 2, "last": "Late December, 2024", "desc": "Given start digit, moveCost, pushCost and targetSeconds, find the minimum fatigue to enter up to four digits (zero-padded to MMSS) whose minutes*60 + seconds = targetSeconds, where each digit press costs pushCost and moving the finger between different digits costs moveCost (starting at startAt). The problem reduces to checking all valid minute/second splits that sum to targetSeconds and computing the minimal move+push cost for their digit sequences.", "page": 2, "cat": "dp", "lc": 2162, "en": "LC 2162. Minimum Cost to Set Cooking Time", "cn": "设置烹饪时间最小代价", "id": "lc2162", "sol": null}, {"title": "String Template Substitution with Variable Replacement", "level": "Mid-level", "reports": 2, "last": "Early January, 2025", "desc": "Implement a string substitution system that replaces placeholders or parts of a string with corresponding values from a given mapping. The solution should handle complex substitution scenarios including nested substitutions where replacement values may contain additional placeholders that need further resolution. Consider using backtracking or iterative approaches to handle all substitution cases correctly.", "page": 3, "cat": "string", "lc": null, "en": "String Template Substitution with Variable Replacement", "cn": "字符串模板变量替换", "id": "string-template-substitution-with-variab", "sol": null}, {"title": "Leetcode 724. Find Pivot Index", "level": "Mid-level", "reports": 2, "last": "Mid December, 2024", "desc": "Find the leftmost index in an integer array where the sum of elements strictly to its left equals the sum strictly to its right, or return -1 if none exists. This is a prefix/suffix-sum problem (solvable in O(n) time by comparing a running left sum to the total).", "page": 3, "cat": "array", "lc": 724, "en": "LC 724. Find Pivot Index", "cn": "寻找数组中心下标", "id": "lc724", "sol": {"ap": "前缀和:左和==总和-左和-当前。", "code": "class Solution:\n    def pivotIndex(self, nums):\n        total = sum(nums); left = 0\n        for i, x in enumerate(nums):\n            if left == total - left - x: return i\n            left += x\n        return -1", "t": "O(n)", "s": "O(1)", "fu": ""}}, {"title": "Leetcode 79. Word Search", "level": "Mid-level", "reports": 2, "last": "Late December, 2024", "desc": "Determine whether a target word can be formed by a path of horizontally or vertically adjacent cells in an m×n letter grid without reusing a cell. The core challenge is performing DFS/backtracking on the grid with visited tracking (and optional pruning) to efficiently explore valid paths.", "page": 3, "cat": "dfs", "lc": 79, "en": "LC 79. Word Search", "cn": "单词搜索", "id": "lc79", "sol": {"ap": "每格启动DFS,seen add->remove回溯;found初始False,返回值要接住。", "code": "class Solution:\n    def exist(self, board, word):\n        m, n = len(board), len(board[0]); seen = set()\n        def dfs(i, j, cnt):\n            if cnt == len(word): return True\n            if (i<0 or i>=m or j<0 or j>=n or (i,j) in seen or board[i][j]!=word[cnt]):\n                return False\n            seen.add((i,j)); found = False\n            for dx,dy in [(0,1),(0,-1),(1,0),(-1,0)]:\n                if dfs(i+dx, j+dy, cnt+1): found = True; break\n            seen.remove((i,j)); return found\n        for i in range(m):\n            for j in range(n):\n                if dfs(i,j,0): return True\n        return False", "t": "O(m·n·3^L)", "s": "O(L)", "fu": "找多个词(#212)→ Trie一次扫;填字游戏(#2018)→ 加方向约束。"}}, {"title": "Leetcode 759. Employee Free Time", "level": "Junior-Mid-level", "reports": 2, "last": "Late December, 2024", "desc": "Given each employee's list of working intervals, compute the finite time intervals when every employee is free by merging/combining overlapping busy intervals across multiple sorted lists and reporting the gaps; this typically uses interval-merge or sweep-line (heap) techniques to handle overlaps across employees.", "page": 3, "cat": "intervals", "lc": 759, "en": "LC 759. Employee Free Time", "cn": "员工空闲时间", "id": "lc759", "sol": {"ap": "摊平→排序→合并→相邻合并区间之间的缝=公共空闲。", "code": "class Solution:\n    def employeeFreeTime(self, schedule):\n        ivs = [iv for emp in schedule for iv in emp]\n        ivs.sort(key=lambda x: x[0])\n        merged = []\n        for iv in ivs:\n            if not merged or merged[-1][1] < iv[0]:\n                merged.append(iv)\n            else:\n                merged[-1][1] = max(merged[-1][1], iv[1])\n        return [[merged[i-1][1], merged[i][0]] for i in range(1, len(merged))]", "t": "O(n log n)", "s": "O(n)", "fu": "每员工区间已有序 → 最小堆 K 路归并 O(n log K)。"}}, {"title": "Leetcode 157. Read N Characters Given Read4", "level": "Mid-level", "reports": 2, "last": "Late December, 2024", "desc": "Given an API read4 that reads up to 4 characters from a file into a temporary buffer, implement read(buf, n) to copy up to n characters into the destination buffer using repeated read4 calls, correctly handling partial reads at EOF and returning the actual number of characters read.", "page": 3, "cat": "design", "lc": 157, "en": "LC 157. Read N Characters Given Read4", "cn": "用Read4读N个字符", "id": "lc157", "sol": null}, {"title": "Leetcode 366. Find Leaves of Binary Tree", "level": "Junior-Mid-level", "reports": 2, "last": "Late December, 2024", "desc": "Given a binary tree, repeatedly remove all current leaf nodes and record their values until the tree is empty, returning a list of lists where each inner list contains the leaves removed in that round. The key challenge is grouping nodes by their removal round (i.e., their height from the bottom), which can be computed via a post-order traversal.", "page": 3, "cat": "dfs", "lc": 366, "en": "LC 366. Find Leaves of Binary Tree", "cn": "找二叉树叶子", "id": "lc366", "sol": {"ap": "后序求高度;节点被摘轮次=高度,按高度分组。", "code": "import collections\nclass Solution:\n    def findLeaves(self, root):\n        res = collections.defaultdict(list)\n        def height(node):\n            if not node: return -1\n            h = 1 + max(height(node.left), height(node.right))\n            res[h].append(node.val); return h\n        height(root)\n        return [res[i] for i in range(max(res)+1)]", "t": "O(n)", "s": "O(h)", "fu": ""}}, {"title": "Leetcode 2115. Find All Possible Recipes from Given Supplies", "level": "Junior-Mid-level", "reports": 2, "last": "Late December, 2024", "desc": "Given recipes whose ingredients may include other recipes and an initial set of supplies, determine which recipes can be produced; the core challenge is dependency resolution on a directed graph (topological ordering or DFS) while handling cycles and using supplies as base nodes.", "page": 3, "cat": "bfs", "lc": 2115, "en": "LC 2115. Find All Possible Recipes from Given Supplies", "cn": "由供给找配方", "id": "lc2115", "sol": {"ap": "拓扑(Kahn):supplies入度0先入队;recipe入度=配料数;料齐解锁。", "code": "from collections import defaultdict, deque\nclass Solution:\n    def findAllRecipes(self, recipes, ingredients, supplies):\n        graph = defaultdict(list); indeg = defaultdict(int)\n        for i, r in enumerate(recipes):\n            for ing in ingredients[i]:\n                graph[ing].append(r); indeg[r] += 1\n        queue = deque(supplies); res = []\n        while queue:\n            item = queue.popleft()\n            for r in graph[item]:\n                indeg[r] -= 1\n                if indeg[r] == 0: res.append(r); queue.append(r)\n        return res", "t": "O(V+E)", "s": "O(V+E)", "fu": "循环依赖 → 入度永不为0,自然排除。"}}, {"title": "Leetcode 20. Valid Parentheses", "level": "Mid-level", "reports": 2, "last": "Late December, 2024", "desc": "Check whether a string of parentheses/brackets is valid by ensuring every closing bracket matches the most recent unmatched opening bracket and the types and nesting order are correct. This is typically solved by tracking openings (e.g., with a stack) and verifying matching pairs.", "page": 3, "cat": "stack", "lc": 20, "en": "LC 20. Valid Parentheses", "cn": "有效括号", "id": "lc20", "sol": {"ap": "左括号入栈,右括号匹配栈顶,最后查空。", "code": "class Solution:\n    def isValid(self, s):\n        stack = []; pairs = {')':'(', ']':'[', '}':'{'}\n        for ch in s:\n            if ch in pairs:\n                if not stack or stack[-1] != pairs[ch]: return False\n                stack.pop()\n            else:\n                stack.append(ch)\n        return not stack", "t": "O(n)", "s": "O(n)", "fu": "最长有效括号(#32)→ DP/栈存下标。"}}, {"title": "Leetcode 729. My Calendar I", "level": "Mid-level", "reports": 2, "last": "Late November, 2024", "desc": "Design a data structure that supports booking half-open intervals [start, end) so that book(start, end) returns true and inserts the interval only if it causes no overlap with existing bookings (otherwise returns false). With up to 1000 calls and times in [0, 1e9], typical solutions check neighbors in a sorted list or use a BST to detect overlaps efficiently.", "page": 4, "cat": "intervals", "lc": 729, "en": "LC 729. My Calendar I", "cn": "我的日程I", "id": "lc729", "sol": {"ap": "暴力存区间,book 时查重叠(s1<e2 and s2<e1);或 SortedList 二分相邻。", "code": "class MyCalendar:\n    def __init__(self):\n        self.books = []\n    def book(self, start, end):\n        for s, e in self.books:\n            if start < e and s < end:\n                return False\n        self.books.append((start, end)); return True", "t": "book O(n)", "s": "O(n)", "fu": "① 允许重叠2次(#731)→ 差分/线段树。② 最大重叠(#732)→ 差分。③ O(log n) → SortedList 二分。"}}, {"title": "Leetcode 3262. Find Overlapping Shifts", "level": "Junior-Mid-level", "reports": 2, "last": "Late November, 2024", "desc": "Given a list of time intervals representing employee shifts, identify overlapping shift pairs or the actual overlapping time segments; the core challenge is detecting interval intersections efficiently (typically via sorting + sweep-line or two-pointer techniques) to handle many intervals and avoid O(n^2) comparisons.", "page": 4, "cat": "intervals", "lc": 3262, "en": "LC 3262. Find Overlapping Shifts", "cn": "重叠班次", "id": "lc3262", "sol": {"ap": "排序+堆统计重叠对:新区间和所有活跃区间都构成重叠。", "code": "import heapq\nclass Solution:\n    def countOverlaps(self, shifts):\n        shifts.sort()\n        heap = []; count = 0\n        for s, e in shifts:\n            while heap and heap[0] < s:\n                heapq.heappop(heap)\n            count += len(heap)\n            heapq.heappush(heap, e)\n        return count", "t": "O(n log n)", "s": "O(n)", "fu": "最大同时重叠数 → len(heap) 峰值。"}}, {"title": "Leetcode 1786. Number of Restricted Paths From First to Last Node", "level": "Junior", "reports": 2, "last": "Mid October, 2024", "desc": "Given a weighted undirected graph, count the number of paths from node 1 to node n such that the shortest distance-to-node-n strictly decreases at every step, returning the result modulo 1e9+7. This requires computing distances to node n and then counting monotone-decreasing paths according to that distance ordering.", "page": 4, "cat": "bfs", "lc": 1786, "en": "LC 1786. Number of Restricted Paths From First to Last Node", "cn": "第一到最后受限路径数", "id": "lc1786", "sol": null}, {"title": "Job Scheduling Algorithms Implementation", "level": "Intern", "reports": 2, "last": "Early October, 2024", "desc": "Implement job scheduling algorithms including both First Come First Serve (FCFS) and priority-based approaches. The solution should handle job submissions with start times, end times, and priorities, and output the execution schedule with appropriate timing details.", "page": 5, "cat": "greedy", "lc": null, "en": "Job Scheduling Algorithms Implementation", "cn": "作业调度算法", "id": "job-scheduling-algorithms-implementation", "sol": null}, {"title": "Leetcode 322. Coin Change", "level": "Mid-level", "reports": 2, "last": "Late September, 2024", "desc": "Given coin denominations available in unlimited quantity and a target amount, find the minimum number of coins needed to form that amount (return -1 if impossible). This is a classic unbounded knapsack / shortest-path-on-integer-states problem (amount ≤ 10^4, up to 12 coin types).", "page": 5, "cat": "dp", "lc": 322, "en": "LC 322. Coin Change", "cn": "零钱兑换", "id": "lc322", "sol": {"ap": "完全背包:dp[x]=min(dp[x],dp[x-c]+1),正序。", "code": "class Solution:\n    def coinChange(self, coins, amount):\n        dp = [float('inf')] * (amount + 1); dp[0] = 0\n        for c in coins:\n            for x in range(c, amount + 1):\n                dp[x] = min(dp[x], dp[x-c] + 1)\n        return dp[amount] if dp[amount] != float('inf') else -1", "t": "O(amount·硬币数)", "s": "O(amount)", "fu": "凑法数(#518)→ dp[x]+=dp[x-c]。0/1倒序,完全正序。"}}, {"title": "Leetcode 1101. The Earliest Moment When Everyone Become Friends", "level": "Mid-level", "reports": 2, "last": "Late September, 2024", "desc": "Given timestamped friendship events among N people, determine the earliest time when the social graph becomes fully connected; process events in chronological order and use a union-find (DSU) to merge components, returning the timestamp when the component count becomes one or -1 if it never does.", "page": 5, "cat": "union-find", "lc": 1101, "en": "LC 1101. The Earliest Moment When Everyone Become Friends", "cn": "最早所有人成为朋友", "id": "lc1101", "sol": {"ap": "按时间排序逐个union,组数变1即全连通,返回当前时刻。", "code": "class Solution:\n    def earliestAcq(self, logs, n):\n        logs.sort(); parent = list(range(n)); self.count = n\n        def find(x):\n            while parent[x] != x:\n                parent[x] = parent[parent[x]]; x = parent[x]\n            return x\n        def union(x, y):\n            rx, ry = find(x), find(y)\n            if rx != ry: parent[rx] = ry; self.count -= 1\n        for t, a, b in logs:\n            union(a, b)\n            if self.count == 1: return t\n        return -1", "t": "O(E log E)", "s": "O(n)", "fu": ""}}, {"title": "Leetcode 770. Basic Calculator IV", "level": "Mid-level", "reports": 2, "last": "Early October, 2024", "desc": "Parse and evaluate a space-separated arithmetic expression with integers, multi-letter variables, parentheses and +, -, * (obeying precedence), applying given variable substitutions, then expand and simplify into polynomial-like terms by multiplying out, combining like terms (summing coefficients), dropping zero coefficients, and returning terms sorted by descending degree and lexicographic order.   Key challenges: implement a parser/evaluator with correct precedence and represent terms as (coefficient, sorted variable multiset) to support multiplication, hashing, and ordering.", "page": 5, "cat": "stack", "lc": 770, "en": "LC 770. Basic Calculator IV", "cn": "基本计算器IV", "id": "lc770", "sol": null}, {"title": "Remove Duplicates with Order Preservation", "level": "Junior", "reports": 2, "last": "Early September, 2024", "desc": "Given an array, remove duplicate elements while maintaining a specific order (either original or reverse) of the remaining elements. Return the modified array with duplicates removed while preserving the required ordering of unique elements.", "page": 6, "cat": "string", "lc": null, "en": "Remove Duplicates with Order Preservation", "cn": "保序去重", "id": "remove-duplicates-with-order-preservatio", "sol": null}, {"title": "Leetcode 2258. Escape the Spreading Fire", "level": "Senior", "reports": 1, "last": "Mid May, 2026", "desc": "Given a grid with grass, fire, and impassable walls, determine the maximum minutes you can wait at (0,0) before starting to move so that you can still reach (m-1,n-1) safely (return -1 if impossible, 1e9 if always safe). The core challenge is reasoning about two competing time-evolving spreads — multi-source fire propagation vs. your timed path — to decide feasibility for different start delays.", "page": 1, "cat": "bfs", "lc": 2258, "en": "LC 2258. Escape the Spreading Fire", "cn": "逃离扩散的火", "id": "lc2258", "sol": {"ap": "多源BFS算火到每格时间→二分等待→BFS验证(终点>=放宽一格)。", "code": "from math import inf\nfrom collections import deque\nclass Solution:\n    def maximumMinutes(self, grid):\n        m, n = len(grid), len(grid[0]); D = [(0,1),(0,-1),(1,0),(-1,0)]\n        fire = [[inf]*n for _ in range(m)]; q = deque()\n        for i in range(m):\n            for j in range(n):\n                if grid[i][j]==1: fire[i][j]=0; q.append((i,j))\n        while q:\n            x, y = q.popleft()\n            for dx,dy in D:\n                nx, ny = x+dx, y+dy\n                if 0<=nx<m and 0<=ny<n and grid[nx][ny]==0 and fire[nx][ny]==inf:\n                    fire[nx][ny] = fire[x][y]+1; q.append((nx,ny))\n        def can(wait):\n            if fire[0][0] <= wait: return False\n            seen = {(0,0)}; q = deque([(0,0,wait)])\n            while q:\n                x, y, t = q.popleft()\n                for dx,dy in D:\n                    nx, ny = x+dx, y+dy\n                    if 0<=nx<m and 0<=ny<n and grid[nx][ny]!=2 and (nx,ny) not in seen:\n                        nt = t+1\n                        if nx==m-1 and ny==n-1:\n                            if fire[nx][ny] >= nt: return True\n                        elif fire[nx][ny] > nt:\n                            seen.add((nx,ny)); q.append((nx,ny,nt))\n            return False\n        lo, hi, ans = 0, m*n, -1\n        while lo <= hi:\n            mid = (lo+hi)//2\n            if can(mid): ans = mid; lo = mid+1\n            else: hi = mid-1\n        return 10**9 if ans == m*n else ans", "t": "O(mn log mn)", "s": "O(mn)", "fu": "火多源、人单源;终点同时到算活。"}}, {"title": "Leetcode 1854. Maximum Population Year", "level": "Senior", "reports": 1, "last": "Mid May, 2026", "desc": "Given birth-death intervals where a person is alive in years [birth, death-1], find the year with the maximum number of overlapping intervals (people alive) and return the earliest such year — a classic sweep-line / prefix-sum over the small 1950–2050 range.", "page": 1, "cat": "intervals", "lc": 1854, "en": "LC 1854. Maximum Population Year", "cn": "人口最多的年份", "id": "lc1854", "sol": {"ap": "差分:出生+1死亡-1,前缀和=当年人口,> 取最早峰值。", "code": "class Solution:\n    def maximumPopulation(self, logs):\n        delta = [0]*2051\n        for b, d in logs:\n            delta[b] += 1; delta[d] -= 1\n        cur = mx = ans = 0\n        for y in range(1950, 2051):\n            cur += delta[y]\n            if cur > mx: mx, ans = cur, y\n        return ans", "t": "O(N+Y)", "s": "O(Y)", "fu": "年份范围很大 → 事件排序扫描线 O(N log N)。"}}, {"title": "Leetcode 1905. Count Sub Islands", "level": "Senior", "reports": 1, "last": "Early May, 2026", "desc": "Count how many islands (4-directionally connected 1s) in grid2 are entirely contained within corresponding land cells in grid1 — traverse each island in grid2 (DFS/BFS) and verify every cell is 1 in grid1.", "page": 1, "cat": "dfs", "lc": 1905, "en": "LC 1905. Count Sub Islands", "cn": "统计子岛屿", "id": "lc1905", "sol": {"ap": "遍历grid2每岛,若某格在grid1是0则非子岛(全称flag)。", "code": "class Solution:\n    def countSubIslands(self, grid1, grid2):\n        m, n = len(grid2), len(grid2[0]); seen = set(); is_sub = True\n        def dfs(i, j):\n            nonlocal is_sub\n            if i<0 or i>=m or j<0 or j>=n or grid2[i][j]==0 or (i,j) in seen: return\n            seen.add((i,j))\n            if grid1[i][j]==0: is_sub = False\n            for dx,dy in [(0,1),(0,-1),(1,0),(-1,0)]: dfs(i+dx, j+dy)\n        count = 0\n        for i in range(m):\n            for j in range(n):\n                if grid2[i][j]==1 and (i,j) not in seen:\n                    is_sub = True; dfs(i,j)\n                    if is_sub: count += 1\n        return count", "t": "O(m·n)", "s": "O(m·n)", "fu": ""}}, {"title": "Leetcode 139. Word Break", "level": "Junior", "reports": 1, "last": "Late March, 2026", "desc": "Determine whether the string s can be segmented into a sequence of one or more words from wordDict (words may be reused). The core challenge is prefix segmentation/reachability over string indices, typically solved with DP or BFS using the dictionary (max word length ≤ 20 limits checks).", "page": 1, "cat": "dp", "lc": 139, "en": "LC 139. Word Break", "cn": "单词拆分", "id": "lc139", "sol": {"ap": "DP:dp[i]=任意切分点 dp[j] and s[j:i]在词典。", "code": "class Solution:\n    def wordBreak(self, s, wordDict):\n        words = set(wordDict); n = len(s)\n        dp = [False] * (n + 1); dp[0] = True\n        for i in range(1, n+1):\n            for j in range(i):\n                if dp[j] and s[j:i] in words:\n                    dp[i] = True; break\n        return dp[-1]", "t": "O(n²·L)", "s": "O(n)", "fu": "输出所有方案(#140)→ 回溯+记忆化;分词最长匹配 → Trie+贪心。"}}, {"title": "Leetcode 2655. Find Maximal Uncovered Ranges", "level": "Senior", "reports": 1, "last": "Mid March, 2026", "desc": "Given a set of possibly overlapping, unsorted intervals within a domain (e.g., [lower, upper]), compute the maximal uncovered ranges—the complement segments not covered by any interval. This requires merging/sorting the input intervals and then finding the gaps (including boundary gaps) between merged intervals.", "page": 1, "cat": "intervals", "lc": 2655, "en": "LC 2655. Find Maximal Uncovered Ranges", "cn": "查找最大未覆盖区间", "id": "lc2655", "sol": {"ap": "补集:ranges 排序,找 [0,n-1] 内未覆盖段。", "code": "class Solution:\n    def findMaximalUncoveredRanges(self, n, ranges):\n        ranges.sort(key=lambda x: x[0])\n        res = []; prev = 0\n        for s, e in ranges:\n            if s > prev:\n                res.append([prev, s-1])\n            prev = max(prev, e+1)\n        if prev <= n-1:\n            res.append([prev, n-1])\n        return res", "t": "O(R log R)", "s": "O(R)", "fu": "动态增删区间 → 平衡树。"}}, {"title": "Leetcode 249. Group Shifted Strings", "level": "Mid-level", "reports": 1, "last": "Mid March, 2026", "desc": "Group strings that are equivalent under a uniform alphabetical shift (e.g., \"abc\" → \"bcd\", with wrap-around) by identifying a shift-invariant signature for each string and grouping those with the same signature.", "page": 1, "cat": "string", "lc": 249, "en": "LC 249. Group Shifted Strings", "cn": "移位字符串分组", "id": "lc249", "sol": {"ap": "按相邻字母差(mod26)做指纹分组。", "code": "from collections import defaultdict\nclass Solution:\n    def groupStrings(self, strings):\n        groups = defaultdict(list)\n        for s in strings:\n            key = tuple((ord(s[i]) - ord(s[i-1])) % 26 for i in range(1, len(s)))\n            groups[key].append(s)\n        return list(groups.values())", "t": "O(N·L)", "s": "O(N·L)", "fu": "字母异位词分组(#49)→ 排序后当key。"}}, {"title": "Leetcode 900. RLE Iterator", "level": "Junior", "reports": 1, "last": "Early March, 2026", "desc": "Create an iterator over a run-length encoded array that, on each next(n) call, consumes n elements by advancing through (count, value) pairs and returns the last value consumed or -1 if the sequence is exhausted. The solution must maintain state across calls and efficiently skip/consume counts (n can be large).", "page": 1, "cat": "design", "lc": 900, "en": "LC 900. RLE Iterator", "cn": "RLE迭代器", "id": "lc900", "sol": {"ap": "指针idx指向计数位;不够吃就跳下一段。", "code": "class RLEIterator:\n    def __init__(self, encoding):\n        self.enc = encoding; self.idx = 0\n    def next(self, n):\n        while self.idx < len(self.enc) and n > self.enc[self.idx]:\n            n -= self.enc[self.idx]; self.idx += 2\n        if self.idx >= len(self.enc): return -1\n        self.enc[self.idx] -= n\n        return self.enc[self.idx+1]", "t": "next 均摊 O(1)", "s": "O(1)", "fu": "计数可达1e9 → 绝不展开,只动指针。"}}, {"title": "Leetcode 588. Design In-Memory File System", "level": "Mid-level", "reports": 1, "last": "Early January, 2026", "desc": "Design an in-memory hierarchical file system that supports path parsing and operations like mkdir, ls, addContentToFile (append/create), and readContentFromFile, requiring you to model directories vs files and maintain file contents. The core challenge is choosing an efficient tree/trie structure to handle traversal, creation, and listing (often lexicographically) while correctly distinguishing files from directories.", "page": 1, "cat": "design", "lc": 588, "en": "LC 588. Design In-Memory File System", "cn": "设计内存文件系统", "id": "lc588", "sol": {"ap": "嵌套dict:目录=dict,文件=str;setdefault 自动建目录。", "code": "class FileSystem:\n    def __init__(self):\n        self.root = {}\n    def _walk(self, path):\n        node = self.root\n        if path == '/': return node\n        for part in path.split('/')[1:]:\n            node = node.setdefault(part, {})\n        return node\n    def ls(self, path):\n        node = self._walk(path)\n        if isinstance(node, str):\n            return [path.split('/')[-1]]\n        return sorted(node.keys())\n    def mkdir(self, path):\n        self._walk(path)\n    def addContentToFile(self, filePath, content):\n        parts = filePath.split('/'); name = parts[-1]\n        node = self._walk('/'.join(parts[:-1]) or '/')\n        node[name] = node.get(name, '') + content\n    def readContentFromFile(self, filePath):\n        return self._walk(filePath)", "t": "ls O(k log k)", "s": "O(总内容)", "fu": "① 求子树大小 → File/Folder 类+多态 get_size 递归。② 频繁查 → 缓存+失效。③ 删目录 → 递归。"}}, {"title": "Leetcode 736. Parse Lisp Expression", "level": "Mid-level", "reports": 1, "last": "Early January, 2026", "desc": "Evaluate a Lisp-like expression string containing integers, variable references, and nested (let / add / mult) forms. The core challenge is parsing the nested syntax and maintaining lexical scoping so let bindings (which may shadow outer variables) are applied correctly while computing the final integer result.", "page": 1, "cat": "stack", "lc": 736, "en": "LC 736. Parse Lisp Expression", "cn": "Lisp表达式解析", "id": "lc736", "sol": null}, {"title": "Leetcode 733. Flood Fill", "level": "Staff", "reports": 1, "last": "Mid November, 2025", "desc": "Given an m×n grid and a starting pixel (sr, sc), repaint all 4-directionally connected cells that have the same color as the starting pixel to the new color and return the updated image. If the new color equals the starting pixel's original color, leave the image unchanged.", "page": 1, "cat": "dfs", "lc": 733, "en": "LC 733. Flood Fill", "cn": "图像渲染(洪水填充)", "id": "lc733", "sol": {"ap": "从起点BFS染色相同旧色连通块。新旧色相同要剪枝防死循环。", "code": "from collections import deque\nclass Solution:\n    def floodFill(self, image, sr, sc, color):\n        old = image[sr][sc]\n        if old == color: return image\n        m, n = len(image), len(image[0])\n        q = deque([(sr, sc)]); image[sr][sc] = color\n        while q:\n            x, y = q.popleft()\n            for dx, dy in [(0,1),(0,-1),(1,0),(-1,0)]:\n                nx, ny = x+dx, y+dy\n                if 0<=nx<m and 0<=ny<n and image[nx][ny]==old:\n                    image[nx][ny] = color; q.append((nx, ny))\n        return image", "t": "O(m·n)", "s": "O(m·n)", "fu": ""}}, {"title": "Leetcode 167. Two Sum II - Input Array Is Sorted", "level": "Mid-level", "reports": 1, "last": "Early November, 2025", "desc": "Given a sorted (non-decreasing) 1-indexed array, find two distinct elements whose sum equals a target and return their 1-based indices. Because the array is sorted and there is exactly one solution, this is typically solved in constant extra space using a two-pointer scan from both ends.", "page": 2, "cat": "array", "lc": 167, "en": "LC 167. Two Sum II - Input Array Is Sorted", "cn": "两数之和II", "id": "lc167", "sol": {"ap": "双指针:和大右移,和小左移(数组已升序)。", "code": "class Solution:\n    def twoSum(self, numbers, target):\n        i, j = 0, len(numbers) - 1\n        while i < j:\n            s = numbers[i] + numbers[j]\n            if s == target: return [i+1, j+1]\n            elif s < target: i += 1\n            else: j -= 1\n        return []", "t": "O(n)", "s": "O(1)", "fu": "未排序→哈希O(n);三数之和(#15)→ 排序+双指针。"}}, {"title": "Leetcode 1102. Path With Maximum Minimum Value", "level": "Mid-level", "reports": 1, "last": "Early October, 2025", "desc": "Given an integer grid where you can move 4-directionally from the top-left to the bottom-right, find a path that maximizes the minimum cell value along the path and return that maximized minimum; this is a maximin path problem typically solved with reachability checks (binary search + BFS/DFS) or a greedy max-heap/Dijkstra-style traversal.", "page": 2, "cat": "bfs", "lc": 1102, "en": "LC 1102. Path With Maximum Minimum Value", "cn": "最大化路径最小值", "id": "lc1102", "sol": {"ap": "最大化路径最小值:max-heap(取负)+min(当前,邻居)松弛。", "code": "import heapq\nclass Solution:\n    def maximumMinimumPath(self, grid):\n        m, n = len(grid), len(grid[0]); seen = {(0,0)}\n        heap = [(-grid[0][0], 0, 0)]\n        while heap:\n            neg, x, y = heapq.heappop(heap); val = -neg\n            if x==m-1 and y==n-1: return val\n            for dx,dy in [(0,1),(0,-1),(1,0),(-1,0)]:\n                nx, ny = x+dx, y+dy\n                if 0<=nx<m and 0<=ny<n and (nx,ny) not in seen:\n                    seen.add((nx,ny))\n                    heapq.heappush(heap, (-min(val, grid[nx][ny]), nx, ny))\n        return -1", "t": "O(mn log mn)", "s": "O(mn)", "fu": "最小化路径最大值(#1631)→ min-heap+max()松弛。"}}, {"title": "Leetcode 3350. Adjacent Increasing Subarrays Detection II", "level": "Senior", "reports": 1, "last": "Late July, 2025", "desc": "Find the largest integer k such that the array contains two adjacent length-k contiguous subarrays (one immediately following the other) that are both strictly increasing. With n up to 2·10^5, this is solved by leveraging lengths of maximal increasing runs (or binary-search over k with linear feasibility checks) rather than brute force.", "page": 2, "cat": "array", "lc": 3350, "en": "LC 3350. Adjacent Increasing Subarrays Detection II", "cn": "相邻递增子数组检测II", "id": "lc3350", "sol": null}, {"title": "Leetcode 1263. Minimum Moves to Move a Box to Their Target Location", "level": "Junior", "reports": 1, "last": "Late June, 2025", "desc": "Given a grid with one player S, one box B, and one target T, find the minimum number of pushes (player moving into the box to move it one cell) to get B to T, where the player can walk on empty cells but cannot pass through the box. This is a shortest-path search in the state space of (box position, player position), requiring checks of player reachability to valid push positions; return -1 if unreachable.", "page": 2, "cat": "bfs", "lc": 1263, "en": "LC 1263. Minimum Moves to Move a Box to Their Target Location", "cn": "将箱子移到目标", "id": "lc1263", "sol": null}, {"title": "Leetcode 1279. Traffic Light Controlled Intersection", "level": "Senior", "reports": 1, "last": "Mid May, 2025", "desc": "Given arrival times/orders of cars and a traffic light that cycles through states, simulate the intersection to determine which cars can pass (and when) under the light's timing constraints. This is an easy event-driven simulation/queueing problem that tests correct handling of timing, ordering, and light state transitions.", "page": 2, "cat": "array", "lc": 1279, "en": "LC 1279. Traffic Light Controlled Intersection", "cn": "红绿灯路口", "id": "lc1279", "sol": null}, {"title": "Leetcode 1381. Design a Stack With Increment Operation", "level": "Mid-level", "reports": 1, "last": "Mid May, 2025", "desc": "Implement a bounded stack (maxSize) supporting push, pop (returning -1 if empty), and increment(k, val) which adds val to the bottom k elements; the core challenge is applying these bottom-k increments efficiently (avoiding O(k) per increment) using lazy/differential bookkeeping so operations are O(1).", "page": 2, "cat": "design", "lc": 1381, "en": "LC 1381. Design a Stack With Increment Operation", "cn": "设计带自增的栈", "id": "lc1381", "sol": {"ap": "list当栈;increment朴素O(k),或懒更新O(1)。", "code": "class CustomStack:\n    def __init__(self, maxSize):\n        self.stack = []; self.max_size = maxSize\n    def push(self, x):\n        if len(self.stack) < self.max_size:\n            self.stack.append(x)\n    def pop(self):\n        return self.stack.pop() if self.stack else -1\n    def increment(self, k, val):\n        for i in range(min(k, len(self.stack))):\n            self.stack[i] += val", "t": "push/pop O(1) · inc O(k)", "s": "O(maxSize)", "fu": "increment频繁 → 懒更新:inc[i]记前缀增量,pop时结算下传,全O(1)。"}}, {"title": "Leetcode 230. Kth Smallest Element in a BST", "level": "Junior", "reports": 1, "last": "Early February, 2025", "desc": "Return the k-th smallest value (1-indexed) in a BST — exploit that an in-order traversal yields values in sorted order and pick the k-th visited node. For frequent updates/queries, augment the BST with subtree sizes (an order-statistic tree) to support O(log n) queries and updates.", "page": 2, "cat": "tree", "lc": 230, "en": "LC 230. Kth Smallest Element in a BST", "cn": "BST第K小", "id": "lc230", "sol": {"ap": "中序遍历(迭代),第k个弹出即第k小。", "code": "class Solution:\n    def kthSmallest(self, root, k):\n        stack, node = [], root\n        while node or stack:\n            while node: stack.append(node); node = node.left\n            node = stack.pop(); k -= 1\n            if k == 0: return node.val\n            node = node.right", "t": "O(h+k)", "s": "O(h)", "fu": "频繁查+改 → 每节点存子树大小,O(log n)。"}}, {"title": "Leetcode 312. Burst Balloons", "level": "Mid-level", "reports": 1, "last": "Late January, 2025", "desc": "Choose an order to remove elements from an array where bursting index i yields coins equal to nums[i-1]*nums[i]*nums[i+1] (treat out-of-bounds as 1), and return the maximum total coins. The reward depends on dynamic neighbors, so the core challenge is exploiting optimal substructure (interval/segment DP over subarrays) to search the best bursting sequence for n up to 300.", "page": 2, "cat": "dp", "lc": 312, "en": "LC 312. Burst Balloons", "cn": "戳气球", "id": "lc312", "sol": {"ap": "区间DP,枚举最后戳的气球k;加虚拟1边界。", "code": "class Solution:\n    def maxCoins(self, nums):\n        nums = [1] + nums + [1]; n = len(nums)\n        dp = [[0]*n for _ in range(n)]\n        for length in range(2, n):\n            for i in range(n - length):\n                j = i + length\n                for k in range(i+1, j):\n                    dp[i][j] = max(dp[i][j], dp[i][k] + dp[k][j] + nums[i]*nums[k]*nums[j])\n        return dp[0][n-1]", "t": "O(n³)", "s": "O(n²)", "fu": "反向思考:枚举最后戳的让子问题独立。"}}, {"title": "Leetcode 30. Substring with Concatenation of All Words", "level": "Mid-level", "reports": 1, "last": "Late January, 2025", "desc": "Given a string s and an array of equal-length words, find all starting indices of substrings in s that are a concatenation of each word exactly once in any order. The core challenge is matching a multiset of fixed-length tokens efficiently (typically with a sliding-window and frequency map) over s.", "page": 2, "cat": "sliding-window", "lc": 30, "en": "LC 30. Substring with Concatenation of All Words", "cn": "串联所有单词的子串", "id": "lc30", "sol": null}, {"title": "Leetcode 2670. Find the Distinct Difference Array", "level": "Junior", "reports": 1, "last": "Late January, 2025", "desc": "Given an array nums, return diff where diff[i] = (number of distinct elements in nums[0..i]) minus (number of distinct elements in nums[i+1..n-1]). This is solved by tracking distinct counts for prefixes and suffixes (e.g., with sets) to compute all differences efficiently.", "page": 2, "cat": "array", "lc": 2670, "en": "LC 2670. Find the Distinct Difference Array", "cn": "找出不同元素差数组", "id": "lc2670", "sol": {"ap": "前缀distinct - 后缀distinct。", "code": "class Solution:\n    def distinctDifferenceArray(self, nums):\n        n = len(nums); res = [0]*n\n        suf = [0]*(n+1); seen = set()\n        for i in range(n-1, -1, -1):\n            seen.add(nums[i]); suf[i] = len(seen)\n        pre = set()\n        for i in range(n):\n            pre.add(nums[i])\n            res[i] = len(pre) - suf[i+1]\n        return res", "t": "O(n)", "s": "O(n)", "fu": ""}}, {"title": "Leetcode 332. Reconstruct Itinerary", "level": "Mid-level", "reports": 1, "last": "Late January, 2025", "desc": "Given a list of directed flight tickets, reconstruct an itinerary starting at \"JFK\" that uses every ticket exactly once and, among all valid itineraries, returns the lexicographically smallest sequence. The core challenge is finding an Eulerian path in a directed graph while prioritizing lexicographically smaller outgoing destinations.", "page": 2, "cat": "bfs", "lc": 332, "en": "LC 332. Reconstruct Itinerary", "cn": "重新规划行程", "id": "lc332", "sol": {"ap": "欧拉路径Hierholzer:目的地排序,DFS走到底,后序入栈,反转。", "code": "from collections import defaultdict\nclass Solution:\n    def findItinerary(self, tickets):\n        graph = defaultdict(list)\n        for src, dst in sorted(tickets, reverse=True):\n            graph[src].append(dst)\n        stack = [\"JFK\"]; res = []\n        while stack:\n            while graph[stack[-1]]:\n                stack.append(graph[stack[-1]].pop())\n            res.append(stack.pop())\n        return res[::-1]", "t": "O(E log E)", "s": "O(E)", "fu": "欧拉走边、节点可重复;拓扑排节点、各一次。"}}, {"title": "Leetcode 3453. Separate Squares I", "level": "Mid-level", "reports": 1, "last": "Mid January, 2025", "desc": "Given axis-aligned squares (xi, yi, li) whose overlaps count multiply, find the smallest horizontal line y such that the sum of areas of all squares above y equals the sum below. The core approach is to exploit that the area difference is monotonic in y and binary-search the y-coordinate, computing each square's above/below contribution by its vertical overlap.", "page": 2, "cat": "segment-tree", "lc": 3453, "en": "LC 3453. Separate Squares I", "cn": "Leetcode 3453. Separate Squares I", "id": "lc3453", "sol": null}, {"title": "Leetcode 149. Max Points on a Line", "level": "Mid-level", "reports": 1, "last": "Mid January, 2025", "desc": "Given up to 300 unique 2D points, return the maximum number that lie on the same straight line. The core challenge is grouping points by slope from each pivot (handling vertical lines and slope precision) to compute the answer in O(n^2) time using normalized slope keys.", "page": 2, "cat": "math", "lc": 149, "en": "LC 149. Max Points on a Line", "cn": "直线上最多的点", "id": "lc149", "sol": {"ap": "枚举每点,统计到其它点斜率,同斜率最多。", "code": "from collections import defaultdict\nfrom math import gcd\nclass Solution:\n    def maxPoints(self, points):\n        n = len(points)\n        if n <= 2: return n\n        res = 1\n        for i in range(n):\n            slopes = defaultdict(int)\n            for j in range(i+1, n):\n                dx = points[j][0]-points[i][0]; dy = points[j][1]-points[i][1]\n                g = gcd(dx, dy) or 1\n                slopes[(dx//g, dy//g)] += 1\n                res = max(res, slopes[(dx//g, dy//g)] + 1)\n        return res", "t": "O(n²)", "s": "O(n)", "fu": "用gcd归一化斜率避免浮点误差。"}}, {"title": "Leetcode 1807. Evaluate the Bracket Pairs of a String", "level": "Junior", "reports": 1, "last": "Early January, 2025", "desc": "Given a string containing non-nested bracketed keys and a list of key→value pairs, replace each \"(key)\" with its corresponding value or \"?\" if the key is unknown. The core challenge is to build a lookup map and perform an efficient single-pass parse (linear time) to reconstruct the resulting string for inputs up to 10^5 characters.", "page": 3, "cat": "stack", "lc": 1807, "en": "LC 1807. Evaluate the Bracket Pairs of a String", "cn": "Leetcode 1807. Evaluate the Bracket Pairs of a String", "id": "lc1807", "sol": null}, {"title": "Leetcode 3205. Maximum Array Hopping Score I", "level": "Junior", "reports": 1, "last": "Early January, 2025", "desc": "Given an integer array, compute the maximum score obtainable by starting at index 0 and repeatedly hopping forward under a constraint (e.g., a maximum jump distance), where your score is the sum of visited elements; this reduces to DP with dp[i] = arr[i] + max(dp[j]) over reachable j and is typically solved with a sliding-window maximum structure (monotonic deque or max-heap) for efficiency.", "page": 3, "cat": "dp", "lc": 3205, "en": "LC 3205. Maximum Array Hopping Score I", "cn": "Leetcode 3205. Maximum Array Hopping Score I", "id": "lc3205", "sol": null}, {"title": "Leetcode 1666. Change the Root of a Binary Tree", "level": "Mid-level", "reports": 1, "last": "Early January, 2025", "desc": "", "page": 3, "cat": "tree", "lc": 1666, "en": "LC 1666. Change the Root of a Binary Tree", "cn": "改变二叉树的根", "id": "lc1666", "sol": {"ap": "反转parent链+子节点搬运:原parent变左孩子,原左孩子变右孩子。", "code": "class Solution:\n    def flipBinaryTree(self, root, leaf):\n        cur = leaf; prev = None\n        while cur != root:\n            nxt = cur.parent\n            if nxt.left is cur: nxt.left = None\n            else: nxt.right = None\n            if cur.left: cur.right = cur.left\n            cur.left = nxt\n            cur.parent = prev\n            prev = cur; cur = nxt\n        root.parent = prev\n        return leaf", "t": "O(h)", "s": "O(1)", "fu": "指针puzzle,纸上先trace。"}}, {"title": "Leetcode 1481. Least Number of Unique Integers after K Removals", "level": "Mid-level", "reports": 1, "last": "Early January, 2025", "desc": "Remove exactly k elements from an integer array to minimize the number of distinct values remaining. This reduces to counting element frequencies and greedily eliminating values with the smallest counts until k is used.", "page": 3, "cat": "greedy", "lc": 1481, "en": "LC 1481. Least Number of Unique Integers after K Removals", "cn": "Leetcode 1481. Least Number of Unique Integers after K Removals", "id": "lc1481", "sol": null}, {"title": "Leetcode 351. Android Unlock Patterns", "level": "Junior", "reports": 1, "last": "Early January, 2025", "desc": "Count the number of valid Android lock patterns on a 3x3 grid with length between m and n, where a move that jumps over a key is allowed only if the intermediate key has already been used. This requires combinatorial search with constraint checking (commonly solved via DFS/backtracking and symmetry-based pruning).", "page": 3, "cat": "dfs", "lc": 351, "en": "LC 351. Android Unlock Patterns", "cn": "安卓解锁模式", "id": "lc351", "sol": null}, {"title": "Leetcode 187. Repeated DNA Sequences", "level": "Principal", "reports": 1, "last": "Late December, 2024", "desc": "Find all distinct 10-letter substrings of a DNA string that occur more than once. This is typically solved by scanning with a sliding window and detecting repeats efficiently using hashing or compact 2-bit encoding to handle lengths up to 10^5.", "page": 3, "cat": "trie", "lc": 187, "en": "LC 187. Repeated DNA Sequences", "cn": "重复DNA序列", "id": "lc187", "sol": {"ap": "10字符滑窗,哈希集合记见过的,出现第二次加答案。", "code": "class Solution:\n    def findRepeatedDnaSequences(self, s):\n        seen = set(); res = set()\n        for i in range(len(s) - 9):\n            sub = s[i:i+10]\n            if sub in seen: res.add(sub)\n            seen.add(sub)\n        return list(res)", "t": "O(n)", "s": "O(n)", "fu": "序列极长 → Rabin-Karp滚动哈希省空间。"}}, {"title": "Leetcode 2296. Design a Text Editor", "level": "Principal", "reports": 1, "last": "Late December, 2024", "desc": "Implement a text editor with a movable cursor that supports inserting text at the cursor, deleting up to k characters to the left (backspace), moving the cursor left/right by k, and returning up to the last 10 characters to the left of the cursor; design a data structure to maintain and update the cursor position and surrounding text efficiently.", "page": 3, "cat": "design", "lc": 2296, "en": "LC 2296. Design a Text Editor", "cn": "设计文本编辑器", "id": "lc2296", "sol": {"ap": "两个栈夹光标,移动光标=字符在两栈间搬运。", "code": "class TextEditor:\n    def __init__(self):\n        self.left = []; self.right = []\n    def addText(self, text):\n        for ch in text: self.left.append(ch)\n    def deleteText(self, k):\n        cnt = min(k, len(self.left))\n        for _ in range(cnt): self.left.pop()\n        return cnt\n    def cursorLeft(self, k):\n        for _ in range(min(k, len(self.left))):\n            self.right.append(self.left.pop())\n        return ''.join(self.left[-10:])\n    def cursorRight(self, k):\n        for _ in range(min(k, len(self.right))):\n            self.left.append(self.right.pop())\n        return ''.join(self.left[-10:])", "t": "各操作 O(k)", "s": "O(总字符)", "fu": "支持undo/redo → 操作栈;大文本 → gap buffer/rope。"}}, {"title": "Leetcode 1756. Design Most Recently Used Queue", "level": "Mid-level", "reports": 1, "last": "Late December, 2024", "desc": "Design a queue-like data structure that maintains items ordered by most-recent access, supporting operations to enqueue, dequeue/remove, and \"touch\" an item to move it to the most-recent position. The challenge is to keep these updates and queries efficient (ideally O(1)) while correctly handling duplicates or capacity constraints if specified.", "page": 3, "cat": "design", "lc": 1756, "en": "LC 1756. Design Most Recently Used Queue", "cn": "设计MRU队列", "id": "lc1756", "sol": {"ap": "朴素 list fetch O(n);优化用树状数组虚拟位置 O(log n)。", "code": "class MRUQueue:\n    def __init__(self, n):\n        self.q = list(range(1, n+1))\n    def fetch(self, k):\n        v = self.q.pop(k-1)\n        self.q.append(v)\n        return v", "t": "fetch O(n) 朴素", "s": "O(n)", "fu": "优化:BIT+虚拟位置,fetch O(log n)。"}}, {"title": "Leetcode 2812. Find the Safest Path in a Grid", "level": "Mid-level", "reports": 1, "last": "Late December, 2024", "desc": "Compute each cell's Manhattan distance to the nearest thief, then find a path from (0,0) to (n-1,n-1) that maximizes the minimum of those distances along the path — a max‑min (bottleneck) path problem on a grid.", "page": 3, "cat": "bfs", "lc": 2812, "en": "LC 2812. Find the Safest Path in a Grid", "cn": "网格中最安全路径", "id": "lc2812", "sol": {"ap": "多源BFS算每格到最近小偷距离→max-heap最大化路径最小safe(同#1102)。", "code": "from collections import deque\nimport heapq\nclass Solution:\n    def maximumSafenessFactor(self, grid):\n        n = len(grid); D = [(0,1),(0,-1),(1,0),(-1,0)]\n        safe = [[-1]*n for _ in range(n)]; q = deque()\n        for i in range(n):\n            for j in range(n):\n                if grid[i][j]==1: safe[i][j]=0; q.append((i,j))\n        while q:\n            x, y = q.popleft()\n            for dx,dy in D:\n                nx, ny = x+dx, y+dy\n                if 0<=nx<n and 0<=ny<n and safe[nx][ny]==-1:\n                    safe[nx][ny] = safe[x][y]+1; q.append((nx,ny))\n        heap = [(-safe[0][0],0,0)]; seen = {(0,0)}\n        while heap:\n            neg, x, y = heapq.heappop(heap); cur = -neg\n            if x==n-1 and y==n-1: return cur\n            for dx,dy in D:\n                nx, ny = x+dx, y+dy\n                if 0<=nx<n and 0<=ny<n and (nx,ny) not in seen:\n                    seen.add((nx,ny))\n                    heapq.heappush(heap, (-min(cur, safe[nx][ny]), nx, ny))\n        return 0", "t": "O(n² log n)", "s": "O(n²)", "fu": "多源BFS+最大化最小,两套路合体。"}}, {"title": "Leetcode 222. Count Complete Tree Nodes", "level": "Mid-level", "reports": 1, "last": "Late December, 2024", "desc": "Given a complete binary tree, return its node count in less than O(n) time by exploiting the tree’s completeness (all full levels except a left-filled last level) to compute subtree heights and identify/count perfect subtrees without visiting every node.", "page": 3, "cat": "tree", "lc": 222, "en": "LC 222. Count Complete Tree Nodes", "cn": "完全二叉树节点数", "id": "lc222", "sol": {"ap": "满子树用公式2^h-1;否则递归左右。O(log²n)。", "code": "class Solution:\n    def countNodes(self, root):\n        if not root: return 0\n        lh = self._h(root, True); rh = self._h(root, False)\n        if lh == rh: return (1 << lh) - 1\n        return 1 + self.countNodes(root.left) + self.countNodes(root.right)\n    def _h(self, node, left):\n        h = 0\n        while node:\n            h += 1; node = node.left if left else node.right\n        return h", "t": "O(log²n)", "s": "O(log n)", "fu": "普通二叉树只能O(n)遍历。"}}, {"title": "Leetcode 394. Decode String", "level": "Mid-level", "reports": 1, "last": "Late December, 2024", "desc": "Decode a string containing nested repeat patterns of the form k[encoded_string], expanding each bracketed segment k times (k may be multi-digit) possibly with multiple nesting levels. Core challenge: parse and evaluate the nested structure correctly and efficiently (e.g., via stack or recursion) to produce the fully decoded string.", "page": 3, "cat": "stack", "lc": 394, "en": "LC 394. Decode String", "cn": "字符串解码", "id": "lc394", "sol": {"ap": "遇[压(当前串,倍数),遇]弹出拼接prev+k*cur。", "code": "class Solution:\n    def decodeString(self, s):\n        stack = []; cur = \"\"; num = 0\n        for ch in s:\n            if ch.isdigit(): num = num*10 + int(ch)\n            elif ch == '[': stack.append((cur, num)); cur, num = \"\", 0\n            elif ch == ']':\n                prev, k = stack.pop(); cur = prev + k*cur\n            else: cur += ch\n        return cur", "t": "O(输出长)", "s": "O(嵌套深度)", "fu": ""}}, {"title": "Leetcode 223. Rectangle Area", "level": "Mid-level", "reports": 1, "last": "Late December, 2024", "desc": "Given coordinates of two axis-aligned rectangles, compute the total area covered by both. The key is to sum their individual areas and subtract the area of their intersection (zero if they don't overlap).", "page": 3, "cat": "math", "lc": 223, "en": "LC 223. Rectangle Area", "cn": "矩形面积", "id": "lc223", "sol": null}, {"title": "Leetcode 416. Partition Equal Subset Sum", "level": "Mid-level", "reports": 1, "last": "Late December, 2024", "desc": "Determine whether the array can be partitioned into two subsets with equal sum — equivalently, check if there exists a subset that sums to half the total. This is a classic 0/1 subset-sum / knapsack problem solvable with DP or bitset techniques since total sum ≤ 200*100.", "page": 3, "cat": "dp", "lc": 416, "en": "LC 416. Partition Equal Subset Sum", "cn": "分割等和子集", "id": "lc416", "sol": {"ap": "转化为子集和=total/2的0/1背包(倒序)。", "code": "class Solution:\n    def canPartition(self, nums):\n        total = sum(nums)\n        if total % 2 == 1: return False\n        target = total // 2\n        dp = [False] * (target + 1); dp[0] = True\n        for num in nums:\n            for j in range(target, num - 1, -1):\n                dp[j] = dp[j] or dp[j - num]\n        return dp[target]", "t": "O(n·target)", "s": "O(target)", "fu": "目标和(#494)、最后石头(#1049)同族。"}}, {"title": "Leetcode 1092. Shortest Common Supersequence", "level": "Mid-level", "reports": 1, "last": "Late December, 2024", "desc": "Find the shortest string that contains both input strings as subsequences — essentially merge them minimizing length by maximizing their overlap. This is solved by dynamic programming to compute the longest common subsequence and reconstruct the shortest common supersequence (O(n*m) time, where n and m ≤ 1000).", "page": 3, "cat": "dp", "lc": 1092, "en": "LC 1092. Shortest Common Supersequence", "cn": "最短公共超序列", "id": "lc1092", "sol": null}, {"title": "Leetcode 2407. Longest Increasing Subsequence II", "level": "Mid-level", "reports": 1, "last": "Late December, 2024", "desc": "Find the length of the longest strictly increasing subsequence of nums such that each adjacent difference is ≤ k. With n up to 1e5 and values bounded, this reduces to DP where dp[x] = 1 + max dp[y] for y in [x-k, x-1], requiring a range-maximum data structure (segment tree / Fenwick) for efficiency.", "page": 4, "cat": "dp", "lc": 2407, "en": "LC 2407. Longest Increasing Subsequence II", "cn": "最长递增子序列II", "id": "lc2407", "sol": null}, {"title": "Leetcode 737. Sentence Similarity II", "level": "Mid-level", "reports": 1, "last": "Late December, 2024", "desc": "Given two equal-length word arrays and a list of similar word pairs where similarity is transitive, determine whether each pair of words at the same index are equivalent (identical or connected through a chain of similarities); this is typically solved by building connectivity (union-find or graph traversal) among words.", "page": 4, "cat": "union-find", "lc": 737, "en": "LC 737. Sentence Similarity II", "cn": "句子相似性II", "id": "lc737", "sol": {"ap": "同义词对union成组;逐位置查相同或同根。传递性→并查集。", "code": "class Solution:\n    def areSentencesSimilarTwo(self, sentence1, sentence2, pairs):\n        if len(sentence1) != len(sentence2): return False\n        parent = {}\n        def find(x):\n            parent.setdefault(x, x)\n            if parent[x] != x: parent[x] = find(parent[x])\n            return parent[x]\n        for a, b in pairs: parent[find(a)] = find(b)\n        return all(w1==w2 or find(w1)==find(w2) for w1,w2 in zip(sentence1, sentence2))", "t": "O((P+N)·α)", "s": "O(词数)", "fu": "句子相似I(#734)不传递,直接哈希对。"}}, {"title": "Leetcode 2675. Array of Objects to Matrix", "level": "Senior", "reports": 1, "last": "Mid December, 2024", "desc": "Convert an array of objects into a 2D matrix by extracting a header row of all unique keys (in a specified order) and aligning each object's values into subsequent rows under the corresponding columns, inserting placeholders for missing keys. The challenge is to efficiently collect and order keys, map them to column indices, and populate the matrix for potentially large inputs while preserving the required column ordering.", "page": 4, "cat": "array", "lc": 2675, "en": "LC 2675. Array of Objects to Matrix", "cn": "Leetcode 2675. Array of Objects to Matrix", "id": "lc2675", "sol": null}, {"title": "Leetcode 1522. Diameter of N-Ary Tree", "level": "Mid-level", "reports": 1, "last": "Mid December, 2024", "desc": "Compute the diameter (longest path in edges between any two nodes) of an N-ary tree by using a post-order traversal to obtain subtree heights and combining the two largest child heights at each node to update a global maximum; this is a tree/DFS problem solvable in O(n) time and O(h) recursion space.", "page": 4, "cat": "tree", "lc": 1522, "en": "LC 1522. Diameter of N-Ary Tree", "cn": "N叉树直径", "id": "lc1522", "sol": {"ap": "后序;每点算最深两条子链之和更新全局,返回单边最深。", "code": "class Solution:\n    def diameter(self, root):\n        self.ans = 0\n        def depth(node):\n            top1 = top2 = 0\n            for ch in node.children:\n                d = depth(ch) + 1\n                if d > top1: top1, top2 = d, top1\n                elif d > top2: top2 = d\n            self.ans = max(self.ans, top1 + top2)\n            return top1\n        depth(root); return self.ans", "t": "O(n)", "s": "O(h)", "fu": "二叉树直径(#543)只比左右两条。"}}, {"title": "Leetcode 2463. Minimum Total Distance Traveled", "level": "Mid-level", "reports": 1, "last": "Mid December, 2024", "desc": "Assign each robot to a factory on the number line (each factory has a repair capacity) so every robot moves left or right to a factory and the total sum of absolute travel distances is minimized. Because crossings don't matter and positions are unique, the core challenge is optimally matching sorted robots to capacitated factories — typically solved with prefix-based dynamic programming.", "page": 4, "cat": "dp", "lc": 2463, "en": "LC 2463. Minimum Total Distance Traveled", "cn": "最小总行驶距离", "id": "lc2463", "sol": null}, {"title": "Leetcode 3439. Reschedule Meetings for Maximum Free Time I", "level": "Mid-level", "reports": 1, "last": "Early December, 2024", "desc": "Given non-overlapping meetings inside [0, eventTime], you may shift up to k meetings (keeping each meeting's duration and the relative order, and staying within the event) to maximize the length of the longest continuous free interval; return that maximum gap. n can be up to 1e5, so an O(n)–O(n log n) strategy (sliding window / DP on intervals) is needed.", "page": 4, "cat": "intervals", "lc": 3439, "en": "LC 3439. Reschedule Meetings for Maximum Free Time I", "cn": "重新安排会议最大空闲", "id": "lc3439", "sol": null}, {"title": "Leetcode 772. Basic Calculator III", "level": "Junior", "reports": 1, "last": "Early December, 2024", "desc": "Evaluate a string arithmetic expression containing integers, +, -, *, /, parentheses and unary signs, respecting operator precedence and parentheses. The challenge is to parse and compute the result (typically via recursive-descent parsing or stack-based evaluation) while handling multi-digit numbers and spaces.", "page": 4, "cat": "stack", "lc": 772, "en": "LC 772. Basic Calculator III", "cn": "基本计算器III", "id": "lc772", "sol": {"ap": "含+-*/(),括号递归求值,括号内优先级栈(*/立即算,+-延迟)。", "code": "class Solution:\n    def calculate(self, s):\n        def helper(it):\n            stack = []; num = 0; op = '+'\n            while True:\n                ch = next(it, ')')\n                if ch.isdigit(): num = num*10 + int(ch)\n                elif ch == '(': num = helper(it)\n                elif ch == ' ': continue\n                else:\n                    if op == '+': stack.append(num)\n                    elif op == '-': stack.append(-num)\n                    elif op == '*': stack.append(stack.pop()*num)\n                    elif op == '/': stack.append(int(stack.pop()/num))\n                    num = 0; op = ch\n                    if ch == ')': break\n            return sum(stack)\n        return helper(iter(s))", "t": "O(n)", "s": "O(n)", "fu": "#224只+-(),#227只+-*/,#772全。"}}, {"title": "Leetcode 2367. Number of Arithmetic Triplets", "level": "Mid-level", "reports": 1, "last": "Late November, 2024", "desc": "Count how many index triplets (i < j < k) in a strictly increasing array form an arithmetic progression with common difference diff, i.e., nums[j]-nums[i] == diff and nums[k]-nums[j] == diff. Equivalently, count values x in nums for which x+diff and x+2*diff also appear.", "page": 4, "cat": "array", "lc": 2367, "en": "LC 2367. Number of Arithmetic Triplets", "cn": "等差三元组数", "id": "lc2367", "sol": null}, {"title": "Leetcode 2050. Parallel Courses III", "level": "Junior", "reports": 1, "last": "Late November, 2024", "desc": "Given a DAG of course prerequisites where each course has a duration and any number of courses can run in parallel once prerequisites are satisfied, compute the minimum time to finish all courses. This is the classic longest-path/critical-path problem on a node-weighted DAG — compute each course's earliest completion time as max(completion times of prerequisites) + its duration.", "page": 4, "cat": "bfs", "lc": 2050, "en": "LC 2050. Parallel Courses III", "cn": "并行课程III", "id": "lc2050", "sol": null}, {"title": "Leetcode 68. Text Justification", "level": "Junior", "reports": 1, "last": "Late November, 2024", "desc": "Pack words greedily into lines of exactly maxWidth characters and insert spaces so each line is fully justified. Extra spaces between words must be distributed as evenly as possible with any leftover spaces placed on the leftmost gaps, while the last line (or a line with a single word) is left-justified.", "page": 4, "cat": "string", "lc": 68, "en": "LC 68. Text Justification", "cn": "文本左右对齐", "id": "lc68", "sol": {"ap": "贪心选每行词,分配空格(左多),最后一行左对齐。", "code": "class Solution:\n    def fullJustify(self, words, maxWidth):\n        res = []; line = []; length = 0\n        for w in words:\n            if length + len(line) + len(w) > maxWidth:\n                for i in range(maxWidth - length):\n                    line[i % (len(line)-1 or 1)] += ' '\n                res.append(''.join(line)); line = []; length = 0\n            line.append(w); length += len(w)\n        res.append(' '.join(line).ljust(maxWidth))\n        return res", "t": "O(n)", "s": "O(n)", "fu": "细节多:单词数=1、最后一行、空格分配。"}}, {"title": "Leetcode 847. Shortest Path Visiting All Nodes", "level": "Mid-level", "reports": 1, "last": "Late November, 2024", "desc": "Find the minimum number of steps in a walk that visits every node of an undirected connected graph (n ≤ 12), where revisiting nodes/edges is allowed. This is solved by searching the shortest path in the augmented state space (current node, visited-node bitmask) — typically via BFS/bitmask DP over O(n·2^n) states.", "page": 4, "cat": "bfs", "lc": 847, "en": "LC 847. Shortest Path Visiting All Nodes", "cn": "访问所有节点的最短路径", "id": "lc847", "sol": {"ap": "状态=(节点,已访问bitmask)的BFS;全访问即答案。", "code": "from collections import deque\nclass Solution:\n    def shortestPathLength(self, graph):\n        n = len(graph)\n        if n == 1: return 0\n        full = (1 << n) - 1\n        q = deque([(i, 1<<i, 0) for i in range(n)])\n        seen = {(i, 1<<i) for i in range(n)}\n        while q:\n            node, mask, d = q.popleft()\n            for nei in graph[node]:\n                nm = mask | (1 << nei)\n                if nm == full: return d + 1\n                if (nei, nm) not in seen:\n                    seen.add((nei, nm)); q.append((nei, nm, d+1))\n        return 0", "t": "O(2^n·n²)", "s": "O(2^n·n)", "fu": "状态压缩BFS经典。"}}, {"title": "Leetcode 251. Flatten 2D Vector", "level": "Mid-level", "reports": 1, "last": "Late November, 2024", "desc": "Implement an iterator over a 2D vector that yields integers in row-major order via next() and hasNext(). The core challenge is maintaining indices and skipping empty inner lists efficiently so iteration remains correct and amortized O(1) per operation.", "page": 4, "cat": "design", "lc": 251, "en": "LC 251. Flatten 2D Vector", "cn": "展开二维向量", "id": "lc251", "sol": {"ap": "(row,col)双指针+_advance()跳空行;next/hasNext都先_advance。", "code": "class Vector2D:\n    def __init__(self, vec):\n        self.vec = vec; self.row = 0; self.col = 0\n    def _advance(self):\n        while self.row < len(self.vec) and self.col == len(self.vec[self.row]):\n            self.row += 1; self.col = 0\n    def next(self):\n        self._advance(); v = self.vec[self.row][self.col]; self.col += 1; return v\n    def hasNext(self):\n        self._advance(); return self.row < len(self.vec)", "t": "均摊 O(1)", "s": "O(1)", "fu": "嵌套任意层(#341)→ 栈存迭代器。"}}, {"title": "Leetcode 1247. Minimum Swaps to Make Strings Equal", "level": "Mid-level", "reports": 1, "last": "Late November, 2024", "desc": "Given two equal-length strings of only 'x' and 'y', compute the minimum number of swaps between the strings (swap s1[i] with s2[j]) to make them identical or return -1 if impossible. Key idea: count mismatches of type \"s1='x', s2='y'\" and \"s1='y', s2='x'\"; pair same-type mismatches (one swap per pair) and handle any two opposite leftovers with two swaps, otherwise it's impossible if total mismatches is odd.", "page": 4, "cat": "greedy", "lc": 1247, "en": "LC 1247. Minimum Swaps to Make Strings Equal", "cn": "使字符串相等最少交换", "id": "lc1247", "sol": {"ap": "只看不匹配两类xy/yx;同类配对1次,跨类2次,总数奇则-1。", "code": "class Solution:\n    def minimumSwap(self, s1, s2):\n        xy = yx = 0\n        for a, b in zip(s1, s2):\n            if a=='x' and b=='y': xy += 1\n            elif a=='y' and b=='x': yx += 1\n        if (xy + yx) % 2 == 1: return -1\n        return xy//2 + yx//2 + (xy % 2) * 2", "t": "O(n)", "s": "O(1)", "fu": ""}}, {"title": "Leetcode 877. Stone Game", "level": "Junior", "reports": 1, "last": "Late November, 2024", "desc": "Two-player zero-sum game on an even-length array where players alternately take an entire pile from either end; determine whether the first player can force a win under optimal play. This is typically solved with interval DP/minimax, though for the given constraints (even number of piles and odd total) Alice can always win.", "page": 4, "cat": "dp", "lc": 877, "en": "LC 877. Stone Game", "cn": "石子游戏", "id": "lc877", "sol": null}, {"title": "Meeting Room Scheduling - Minimum Rooms Required", "level": "Mid-level", "reports": 1, "last": "Mid November, 2024", "desc": "Given a list of meeting time intervals, determine the minimum number of conference rooms required so that no meetings overlap. This may involve handling 'Do Not Schedule' periods where meetings should be cut to avoid conflicts. The core challenge is computing the maximum number of concurrent intervals, typically solved via sorting with a min-heap of end times or a sweep-line algorithm of start/end events.", "page": 4, "cat": "intervals", "lc": null, "en": "Meeting Room Scheduling - Minimum Rooms Required", "cn": "会议室调度-最少房间", "id": "meeting-room-scheduling-minimum-rooms-re", "sol": null}, {"title": "Leetcode 413. Arithmetic Slices", "level": "Intern", "reports": 1, "last": "Mid November, 2024", "desc": "Count how many contiguous subarrays of length at least three form an arithmetic sequence (i.e., have the same difference between consecutive elements). The task reduces to finding runs where consecutive differences are equal and summing the number of distinct length-≥3 slices within each run.", "page": 4, "cat": "dp", "lc": 413, "en": "LC 413. Arithmetic Slices", "cn": "等差数列划分", "id": "lc413", "sol": null}, {"title": "Leetcode 975. Odd Even Jump", "level": "Mid-level", "reports": 1, "last": "Early November, 2024", "desc": "Count how many starting indices can reach the end of an array by alternating odd/even jumps where an odd jump goes to the smallest-index j>i with arr[j] >= arr[i] and an even jump goes to the smallest-index j>i with arr[j] <= arr[i]. The core challenge is efficiently precomputing these next-higher/next-lower targets (e.g., via sorting + monotonic stack or an ordered map) and using DP to track which indices can reach the end.", "page": 4, "cat": "mono-stack", "lc": 975, "en": "LC 975. Odd Even Jump", "cn": "奇偶跳", "id": "lc975", "sol": null}, {"title": "Leetcode 150. Evaluate Reverse Polish Notation", "level": "Mid-level", "reports": 1, "last": "Early November, 2024", "desc": "Evaluate the integer value of an expression given in Reverse Polish Notation, where tokens are integers or the operators +, -, *, / and all intermediate results fit in 32-bit. The core challenge is to process tokens in one pass (commonly with a stack), applying operators to operands and ensuring division truncates toward zero.", "page": 4, "cat": "stack", "lc": 150, "en": "LC 150. Evaluate Reverse Polish Notation", "cn": "逆波兰表达式求值", "id": "lc150", "sol": {"ap": "栈:数字入栈,运算符弹两个算完压回。", "code": "class Solution:\n    def evalRPN(self, tokens):\n        stack = []\n        for t in tokens:\n            if t in ('+','-','*','/'):\n                b = stack.pop(); a = stack.pop()\n                if t == '+': stack.append(a+b)\n                elif t == '-': stack.append(a-b)\n                elif t == '*': stack.append(a*b)\n                else: stack.append(int(a/b))\n            else: stack.append(int(t))\n        return stack[0]", "t": "O(n)", "s": "O(n)", "fu": "中缀表达式(#224/227/772)→ 双栈或递归。"}}, {"title": "Leetcode 444. Sequence Reconstruction", "level": "Junior", "reports": 1, "last": "Late October, 2024", "desc": "Given an original sequence and a list of subsequences, determine whether those subsequences uniquely determine the original order — equivalently, whether the precedence constraints induce a unique topological ordering equal to the given sequence. Model subsequences as directed edges and check that a topological sort exists and is unique (only one candidate with indegree zero at each step) matching the original.", "page": 4, "cat": "bfs", "lc": 444, "en": "LC 444. Sequence Reconstruction", "cn": "序列重建", "id": "lc444", "sol": null}, {"title": "Leetcode 3190. Find Minimum Operations to Make All Elements Divisible by Three", "level": "Mid-level", "reports": 1, "last": "Late October, 2024", "desc": "Compute each element's remainder mod 3 and for each add the minimum moves to reach 0 (min(r, 3−r)), which reduces here to counting all elements with remainder 1 or 2 — their count is the minimum number of ±1 operations needed.", "page": 4, "cat": "array", "lc": 3190, "en": "LC 3190. Find Minimum Operations to Make All Elements Divisible by Three", "cn": "使元素整除3最小操作", "id": "lc3190", "sol": null}, {"title": "Leetcode 850. Rectangle Area II", "level": "Mid-level", "reports": 1, "last": "Late October, 2024", "desc": "Compute the union area of up to 200 axis-aligned rectangles with coordinates up to 1e9, counting overlapping regions only once and returning the result modulo 1e9+7. This is typically solved with an x-axis sweep line that accumulates area using the total covered y-length at each x-interval (maintained via interval merging or a segment tree after coordinate compression).", "page": 5, "cat": "segment-tree", "lc": 850, "en": "LC 850. Rectangle Area II", "cn": "矩形面积II", "id": "lc850", "sol": null}, {"title": "Leetcode 2542. Maximum Subsequence Score", "level": "Mid-level", "reports": 1, "last": "Late October, 2024", "desc": "Pick k indices to maximize (sum of chosen nums1 values) * (minimum of the chosen nums2 values); the core challenge is trading off a large nums1 sum against keeping the nums2 minimum high. A common pattern is to treat each nums2 as a candidate minimum (by sorting nums2 descending) and greedily maintain the largest nums1 contributions (e.g., with a min-heap) to evaluate the best product.", "page": 5, "cat": "heap", "lc": 2542, "en": "LC 2542. Maximum Subsequence Score", "cn": "最大子序列分数", "id": "lc2542", "sol": {"ap": "按nums2降序排,枚举每个作为最小因子,前面取nums1最大k个。", "code": "import heapq\nclass Solution:\n    def maxScore(self, nums1, nums2, k):\n        pairs = sorted(zip(nums2, nums1), reverse=True)\n        heap = []; cur = 0; res = 0\n        for n2, n1 in pairs:\n            heapq.heappush(heap, n1); cur += n1\n            if len(heap) > k: cur -= heapq.heappop(heap)\n            if len(heap) == k: res = max(res, cur * n2)\n        return res", "t": "O(n log n)", "s": "O(n)", "fu": ""}}, {"title": "Leetcode 252. Meeting Rooms", "level": "Intern", "reports": 1, "last": "Late October, 2024", "desc": "Given a list of meeting time intervals [start, end], determine whether any two intervals overlap so a single person can attend all meetings; this is essentially an interval-overlap detection problem typically solved by sorting intervals by start time and checking adjacent intervals.", "page": 5, "cat": "intervals", "lc": 252, "en": "LC 252. Meeting Rooms", "cn": "会议室", "id": "lc252", "sol": {"ap": "按 start 排序,相邻重叠则无法全部参加。", "code": "class Solution:\n    def canAttendMeetings(self, intervals):\n        intervals.sort(key=lambda x: x[0])\n        for i in range(1, len(intervals)):\n            if intervals[i][0] < intervals[i-1][1]:\n                return False\n        return True", "t": "O(n log n)", "s": "O(1)", "fu": "求最少房间 → #253 用堆。"}}, {"title": "Optimize Meeting Point for Friends in a Graph", "level": "Mid-level", "reports": 1, "last": "Mid October, 2024", "desc": "Given a graph with n friends at different locations and m possible meeting points (restaurants/cafes), find the optimal meeting location. The goal is to minimize either the total travel time or the maximum time for any friend to reach the meeting point. Each edge in the graph represents a path with unit distance taking unit time to travel.", "page": 5, "cat": "intervals", "lc": null, "en": "Optimize Meeting Point for Friends in a Graph", "cn": "图中朋友最佳会面点", "id": "optimize-meeting-point-for-friends-in-a-", "sol": null}, {"title": "Leetcode 104. Maximum Depth of Binary Tree", "level": "Junior", "reports": 1, "last": "Mid October, 2024", "desc": "Given the root of a binary tree, return its maximum depth — the number of nodes along the longest root-to-leaf path. This classic easy problem is solved by a DFS or level-order traversal in O(n) time (n ≤ 10^4).", "page": 5, "cat": "tree", "lc": 104, "en": "LC 104. Maximum Depth of Binary Tree", "cn": "二叉树最大深度", "id": "lc104", "sol": {"ap": "递归:max(左深,右深)+1。", "code": "class Solution:\n    def maxDepth(self, root):\n        if not root: return 0\n        return 1 + max(self.maxDepth(root.left), self.maxDepth(root.right))", "t": "O(n)", "s": "O(h)", "fu": "直径 → 后序返回深度同时更新全局max(左+右)。"}}, {"title": "Leetcode 191. Number of 1 Bits", "level": "Junior", "reports": 1, "last": "Mid October, 2024", "desc": "Count the Hamming weight (number of 1 bits) in the binary representation of a 32-bit integer. For many repeated calls, you can optimize by caching or using a precomputed bit-count lookup table.", "page": 5, "cat": "math", "lc": 191, "en": "LC 191. Number of 1 Bits", "cn": "位1的个数", "id": "lc191", "sol": null}, {"title": "Leetcode 1109. Corporate Flight Bookings", "level": "Junior", "reports": 1, "last": "Mid October, 2024", "desc": "Given n flights and bookings [first, last, seats] that add seats to every flight in a range, compute the final seats per flight; the core challenge is applying many range additions efficiently (use a difference array + prefix sum to get O(n + m) time).", "page": 5, "cat": "intervals", "lc": 1109, "en": "LC 1109. Corporate Flight Bookings", "cn": "航班预订统计", "id": "lc1109", "sol": {"ap": "差分:[l,r]在 l 处+seats,r+1 处-seats,前缀和还原。", "code": "class Solution:\n    def corpFlightBookings(self, bookings, n):\n        diff = [0]*(n+1)\n        for l, r, seats in bookings:\n            diff[l-1] += seats; diff[r] -= seats\n        for i in range(1, n):\n            diff[i] += diff[i-1]\n        return diff[:n]", "t": "O(n+m)", "s": "O(n)", "fu": "二维差分处理矩阵区域加。"}}, {"title": "Leetcode 2284. Sender With Largest Word Count", "level": "Junior", "reports": 1, "last": "Mid October, 2024", "desc": "Sum each sender's total words across their messages and return the sender with the highest word count; if there’s a tie, return the case-sensitive lexicographically largest name.", "page": 5, "cat": "array", "lc": 2284, "en": "LC 2284. Sender With Largest Word Count", "cn": "发件人最大单词数", "id": "lc2284", "sol": null}, {"title": "Leetcode 3047. Find the Largest Area of Square Inside Two Rectangles", "level": "Junior", "reports": 1, "last": "Mid October, 2024", "desc": "Given a set of axis-aligned rectangles, find the largest-area axis-aligned square that can fit entirely inside the intersection region of at least two rectangles. The core challenge is geometric: for overlapping rectangle pairs compute their intersection rectangle and use the smaller of its width and height as the maximum square side, returning the largest such area (or 0).", "page": 5, "cat": "array", "lc": 3047, "en": "LC 3047. Find the Largest Area of Square Inside Two Rectangles", "cn": "正方形最大面积", "id": "lc3047", "sol": null}, {"title": "Leetcode 290. Word Pattern", "level": "Mid-level", "reports": 1, "last": "Mid October, 2024", "desc": "Check whether the characters in pattern and the space-separated words in s have a bijective (one-to-one and onto) mapping that preserves order — i.e., each pattern letter maps to exactly one word and no two letters map to the same word, and substituting letters with their mapped words reproduces s.", "page": 5, "cat": "array", "lc": 290, "en": "LC 290. Word Pattern", "cn": "单词规律", "id": "lc290", "sol": {"ap": "双向映射:词<->模式字符,任一冲突即False。", "code": "class Solution:\n    def wordPattern(self, pattern, s):\n        words = s.split()\n        if len(pattern) != len(words): return False\n        c2w, w2c = {}, {}\n        for c, w in zip(pattern, words):\n            if c in c2w and c2w[c] != w: return False\n            if w in w2c and w2c[w] != c: return False\n            c2w[c] = w; w2c[w] = c\n        return True", "t": "O(n)", "s": "O(n)", "fu": "同构字符串(#205)同款双映射。"}}, {"title": "Web Content Parsing and Traversal Algorithms", "level": "Mid-level", "reports": 1, "last": "Mid October, 2024", "desc": "This question involves parsing web content (HTML documents or webpages) and applying tree/graph traversal algorithms. Tasks include converting HTML to tree structures, implementing search functions for specific content, and using BFS to crawl and map URLs. The core challenges are efficient parsing, tree construction, and implementing appropriate traversal algorithms for web content analysis.", "page": 5, "cat": "design", "lc": null, "en": "Web Content Parsing and Traversal Algorithms", "cn": "网页内容解析遍历", "id": "web-content-parsing-and-traversal-algori", "sol": null}, {"title": "Leetcode 217. Contains Duplicate", "level": "Mid-level", "reports": 1, "last": "Mid October, 2024", "desc": "Return true if any integer appears at least twice in the array and false if all elements are distinct. Array length can be up to 1e5 with values up to ±1e9.", "page": 5, "cat": "array", "lc": 217, "en": "LC 217. Contains Duplicate", "cn": "存在重复", "id": "lc217", "sol": {"ap": "哈希集合,见过即重复。", "code": "class Solution:\n    def containsDuplicate(self, nums):\n        return len(set(nums)) != len(nums)", "t": "O(n)", "s": "O(n)", "fu": "距离k内重复(#219)→ 滑窗集合。"}}, {"title": "Leetcode 1296. Divide Array in Sets of K Consecutive Numbers", "level": "Mid-level", "reports": 1, "last": "Mid October, 2024", "desc": "Determine if the multiset of integers can be partitioned into groups of size k where each group consists of k consecutive numbers. This requires that the array length is divisible by k and the element frequencies permit greedily forming consecutive runs in increasing order.", "page": 5, "cat": "greedy", "lc": 1296, "en": "LC 1296. Divide Array in Sets of K Consecutive Numbers", "cn": "划分数组为连续数字集", "id": "lc1296", "sol": null}, {"title": "Leetcode 362. Design Hit Counter", "level": "Mid-level", "reports": 1, "last": "Early October, 2024", "desc": "Design a hit counter that records timestamps of hits and returns the number of hits in the past 5 minutes (300 seconds). The challenge is to support high-frequency record and query operations efficiently by maintaining a sliding-window summary (e.g., queue or fixed-size circular buffer) that discards expired hits.", "page": 5, "cat": "design", "lc": 362, "en": "LC 362. Design Hit Counter", "cn": "设计点击计数器", "id": "lc362", "sol": {"ap": "deque存时间戳;getHits弹出300秒前的。", "code": "from collections import deque\nclass HitCounter:\n    def __init__(self):\n        self.q = deque()\n    def hit(self, timestamp):\n        self.q.append(timestamp)\n    def getHits(self, timestamp):\n        while self.q and self.q[0] <= timestamp - 300:\n            self.q.popleft()\n        return len(self.q)", "t": "均摊 O(1)", "s": "O(窗口hit数)", "fu": "并发高 → 环形数组按秒分桶,O(1)固定空间。"}}, {"title": "Leetcode 2726. Calculator with Method Chaining", "level": "Mid-level", "reports": 1, "last": "Early October, 2024", "desc": "Implement a Calculator class whose constructor takes an initial numeric result and provides add, subtract, multiply, divide (throw \"Division by zero is not allowed\" for divisor 0), and power methods that each return the Calculator to allow method chaining, plus getResult to return the final value. Results within 1e-5 of the expected value are accepted.", "page": 5, "cat": "design", "lc": 2726, "en": "LC 2726. Calculator with Method Chaining", "cn": "链式方法计算器", "id": "lc2726", "sol": null}, {"title": "Leetcode 75. Sort Colors", "level": "Intern", "reports": 1, "last": "Early October, 2024", "desc": "Reorder an array of values 0, 1, and 2 in-place so all 0s come first, then 1s, then 2s (the Dutch National Flag problem); aim for a one-pass, constant-extra-space solution without using built-in sort.", "page": 5, "cat": "array", "lc": 75, "en": "LC 75. Sort Colors", "cn": "颜色分类", "id": "lc75", "sol": {"ap": "三指针荷兰国旗:0换前,2换后。", "code": "class Solution:\n    def sortColors(self, nums):\n        lo, mid, hi = 0, 0, len(nums) - 1\n        while mid <= hi:\n            if nums[mid] == 0:\n                nums[lo], nums[mid] = nums[mid], nums[lo]; lo += 1; mid += 1\n            elif nums[mid] == 2:\n                nums[mid], nums[hi] = nums[hi], nums[mid]; hi -= 1\n            else: mid += 1", "t": "O(n)", "s": "O(1)", "fu": "k种颜色 → 计数排序两趟。"}}, {"title": "Leetcode 415. Add Strings", "level": "Junior", "reports": 1, "last": "Early October, 2024", "desc": "Given two non-negative integers as decimal strings, return their sum as a string by simulating digit-by-digit addition from the least significant digits with carry (no integer conversion or big-integer libraries allowed). Inputs can be large (length up to 10^4), so the solution must handle arbitrary-length strings.", "page": 5, "cat": "math", "lc": 415, "en": "LC 415. Add Strings", "cn": "字符串相加", "id": "lc415", "sol": null}, {"title": "Leetcode 463. Island Perimeter", "level": "Junior", "reports": 1, "last": "Early October, 2024", "desc": "Given a rectangular grid with exactly one island of orthogonally connected land cells, compute the island's perimeter by summing the edges of land cells that are adjacent to water or the grid boundary (equivalently use 4*land_cells - 2*shared_edges). Grid dimensions ≤100 and connections are only horizontal/vertical.", "page": 5, "cat": "dfs", "lc": 463, "en": "LC 463. Island Perimeter", "cn": "岛屿周长", "id": "lc463", "sol": {"ap": "每陆地4边,每对相邻陆地减2。", "code": "class Solution:\n    def islandPerimeter(self, grid):\n        m, n = len(grid), len(grid[0]); peri = 0\n        for i in range(m):\n            for j in range(n):\n                if grid[i][j] == 1:\n                    peri += 4\n                    if i>0 and grid[i-1][j]==1: peri -= 2\n                    if j>0 and grid[i][j-1]==1: peri -= 2\n        return peri", "t": "O(m·n)", "s": "O(1)", "fu": ""}}, {"title": "Leetcode 1166. Design File System", "level": "Intern", "reports": 1, "last": "Early October, 2024", "desc": "Implement an in-memory hierarchical file system that supports createPath(path, value) — which should succeed only if the immediate parent path exists and the path is new — and get(path) returning the stored value or -1 if absent. The challenge is efficiently enforcing parent-existence and uniqueness checks for arbitrary path strings.", "page": 5, "cat": "design", "lc": 1166, "en": "LC 1166. Design File System", "cn": "设计文件系统", "id": "lc1166", "sol": {"ap": "嵌套dict存路径,创建时校验父路径存在。", "code": "class FileSystem:\n    def __init__(self):\n        self.paths = {}\n    def createPath(self, path, value):\n        if path in self.paths or path == '/': return False\n        parent = path[:path.rfind('/')]\n        if parent and parent not in self.paths: return False\n        self.paths[path] = value; return True\n    def get(self, path):\n        return self.paths.get(path, -1)", "t": "O(路径长)", "s": "O(路径数)", "fu": ""}}, {"title": "Evaluate and Simplify Mathematical Expressions", "level": "Junior", "reports": 1, "last": "Early October, 2024", "desc": "Design an algorithm to parse, evaluate, and simplify mathematical expressions. The expressions may contain arithmetic operators (+, -, *, /), variables, and parentheses. Handle operator precedence correctly and support both numeric evaluation and algebraic simplification. The solution should efficiently handle complex expressions and multiple queries.", "page": 5, "cat": "string", "lc": null, "en": "Evaluate and Simplify Mathematical Expressions", "cn": "求值并化简数学表达式", "id": "evaluate-and-simplify-mathematical-expre", "sol": null}, {"title": "Leetcode 1202. Smallest String With Swaps", "level": "Senior", "reports": 1, "last": "Early October, 2024", "desc": "Given a string and allowed index swap pairs, view pairs as edges in a graph to find connected components where characters can be freely permuted; for each component, sort its characters and place them in the component's indices to produce the lexicographically smallest string. This requires near-linear component-finding (union-find or DFS) and sorting per component to handle up to 1e5 elements.", "page": 6, "cat": "union-find", "lc": 1202, "en": "LC 1202. Smallest String With Swaps", "cn": "交换字符串元素", "id": "lc1202", "sol": {"ap": "同组下标可任意交换→并查集分组,每组排序后填回。", "code": "from collections import defaultdict\nclass Solution:\n    def smallestStringWithSwaps(self, s, pairs):\n        n = len(s); parent = list(range(n))\n        def find(x):\n            while parent[x]!=x: parent[x]=parent[parent[x]]; x=parent[x]\n            return x\n        for a, b in pairs: parent[find(a)] = find(b)\n        groups = defaultdict(list)\n        for i in range(n): groups[find(i)].append(i)\n        res = list(s)\n        for idxs in groups.values():\n            chars = sorted(res[i] for i in idxs)\n            for i, c in zip(sorted(idxs), chars): res[i] = c\n        return ''.join(res)", "t": "O(n log n)", "s": "O(n)", "fu": ""}}, {"title": "Leetcode 2259. Remove Digit From Number to Maximize Result", "level": "Junior", "reports": 1, "last": "Early October, 2024", "desc": "Given a numeric string and a target digit that occurs at least once, remove exactly one occurrence of that digit so the remaining string represents the largest possible integer. The core challenge is selecting which occurrence to remove (a greedy positional choice) while preserving the original order.", "page": 6, "cat": "greedy", "lc": 2259, "en": "LC 2259. Remove Digit From Number to Maximize Result", "cn": "移除数字使结果最大", "id": "lc2259", "sol": null}, {"title": "Leetcode 2662. Minimum Cost of a Path With Special Roads", "level": "Mid-level", "reports": 1, "last": "Late September, 2024", "desc": "Find the minimum cost to go from start to target in a 2D grid where moving anywhere costs Manhattan distance but there are directed \"special roads\" (fixed-cost shortcuts between given points, reusable) that may reduce cost. Model start, target and all road endpoints as graph nodes with edges for Manhattan distances and directed special-road edges, then compute the shortest path (e.g., Dijkstra).", "page": 6, "cat": "bfs", "lc": 2662, "en": "LC 2662. Minimum Cost of a Path With Special Roads", "cn": "特殊路径最小代价", "id": "lc2662", "sol": null}, {"title": "Leetcode 617. Merge Two Binary Trees", "level": "Mid-level", "reports": 1, "last": "Late September, 2024", "desc": "Given two binary trees, merge them into a new tree by traversing both from the roots and summing the values of overlapping nodes while using the non-null node when one side is missing. This is typically solved with a simultaneous DFS/BFS traversal (often recursive) that combines corresponding nodes.", "page": 6, "cat": "tree", "lc": 617, "en": "LC 617. Merge Two Binary Trees", "cn": "合并二叉树", "id": "lc617", "sol": {"ap": "同步递归合并:都非空则相加,否则取非空。", "code": "class Solution:\n    def mergeTrees(self, root1, root2):\n        if not root1: return root2\n        if not root2: return root1\n        root1.val += root2.val\n        root1.left = self.mergeTrees(root1.left, root2.left)\n        root1.right = self.mergeTrees(root1.right, root2.right)\n        return root1", "t": "O(n)", "s": "O(h)", "fu": ""}}, {"title": "Leetcode 785. Is Graph Bipartite?", "level": "Junior", "reports": 1, "last": "Late September, 2024", "desc": "Given an undirected graph as adjacency lists (possibly disconnected), determine whether it is bipartite — i.e., can its vertices be two-colored so no adjacent vertices share a color — which reduces to detecting a conflict/odd cycle via graph traversal (BFS/DFS).", "page": 6, "cat": "bfs", "lc": 785, "en": "LC 785. Is Graph Bipartite?", "cn": "判断二分图", "id": "lc785", "sol": {"ap": "BFS二染色;相邻同色则非二分图。", "code": "from collections import deque\nclass Solution:\n    def isBipartite(self, graph):\n        n = len(graph); color = {}\n        for s in range(n):\n            if s in color: continue\n            color[s] = 0; q = deque([s])\n            while q:\n                u = q.popleft()\n                for v in graph[u]:\n                    if v not in color:\n                        color[v] = color[u] ^ 1; q.append(v)\n                    elif color[v] == color[u]:\n                        return False\n        return True", "t": "O(V+E)", "s": "O(V)", "fu": "并查集:把邻居和u的对立组合并。"}}, {"title": "Leetcode 753. Cracking the Safe", "level": "Junior", "reports": 1, "last": "Late September, 2024", "desc": "Find the shortest string over digits 0..k-1 such that every possible length-n password appears as a contiguous substring (i.e., produce a de Bruijn sequence of order n on k symbols). This is typically solved by building the de Bruijn graph of k^{n-1} nodes and finding an Eulerian cycle (Hierholzer's algorithm).", "page": 6, "cat": "greedy", "lc": 753, "en": "LC 753. Cracking the Safe", "cn": "破解保险箱", "id": "lc753", "sol": null}, {"title": "Leetcode 843. Guess the Word", "level": "Mid-level", "reports": 1, "last": "Late September, 2024", "desc": "Given a list of unique six-letter words and an API that, for any guessed word from the list, returns the number of characters that match the secret in both value and position, identify the secret within a limited number of guesses. The core challenge is designing a guessing strategy (e.g., minimax or information-gain elimination) that efficiently prunes candidates based on match counts to guarantee finding the secret within allowedGuesses.", "page": 6, "cat": "greedy", "lc": 843, "en": "LC 843. Guess the Word", "cn": "猜单词", "id": "lc843", "sol": null}, {"title": "Leetcode 2098. Subsequence of Size K With the Largest Even Sum", "level": "Junior", "reports": 1, "last": "Mid September, 2024", "desc": "Pick exactly k elements from an array to maximize their sum under the constraint that the sum must be even. Typical approach is greedy: take the k largest values, and if their sum is odd, adjust parity by swapping the smallest odd/even chosen element with the best opposite-parity candidate outside the selection (use sorting/heaps to find those quickly).", "page": 6, "cat": "array", "lc": 2098, "en": "LC 2098. Subsequence of Size K With the Largest Even Sum", "cn": "最大和长度K子序列", "id": "lc2098", "sol": null}, {"title": "Leetcode 2772. Apply Operations to Make All Array Elements Equal to Zero", "level": "Junior", "reports": 1, "last": "Mid September, 2024", "desc": "Determine whether you can reduce all elements of nums to zero by repeatedly subtracting 1 from any contiguous subarray of length k. The core challenge is deciding feasibility of windowed decrements, typically solved with a left-to-right greedy that tracks cumulative range effects (difference/sliding-window) in O(n).", "page": 6, "cat": "greedy", "lc": 2772, "en": "LC 2772. Apply Operations to Make All Array Elements Equal to Zero", "cn": "使数组元素相等", "id": "lc2772", "sol": null}, {"title": "Leetcode 452. Minimum Number of Arrows to Burst Balloons", "level": "Mid-level", "reports": 1, "last": "Mid September, 2024", "desc": "Given a list of intervals [x_start, x_end] (endpoints inclusive), find the minimum number of points on the x-axis (vertical arrows) such that each interval contains at least one point. This is the classic interval-stabbing/covering problem: choose the fewest x positions that hit all intervals.", "page": 6, "cat": "intervals", "lc": 452, "en": "LC 452. Minimum Number of Arrows to Burst Balloons", "cn": "戳破气球最少箭", "id": "lc452", "sol": {"ap": "按 end 排序,贪心射箭:能覆盖就不加箭。", "code": "class Solution:\n    def findMinArrowShots(self, points):\n        points.sort(key=lambda x: x[1])\n        arrows = 0; end = float('-inf')\n        for s, e in points:\n            if s > end:\n                arrows += 1; end = e\n        return arrows", "t": "O(n log n)", "s": "O(1)", "fu": "无重叠区间个数(#435)同款。"}}, {"title": "Determine if All Intervals Have a Common Intersection", "level": "Mid-level", "reports": 1, "last": "Mid September, 2024", "desc": "Given a set of intervals, determine if all intervals have anything in common.", "page": 6, "cat": "array", "lc": null, "en": "Determine if All Intervals Have a Common Intersection", "cn": "判断所有区间是否有公共交集", "id": "determine-if-all-intervals-have-a-common", "sol": null}, {"title": "Leetcode 1288. Remove Covered Intervals", "level": "Mid-level", "reports": 1, "last": "Mid September, 2024", "desc": "Given a list of half-open intervals [l, r), remove any interval that is fully contained within another (c ≤ a and b ≤ d) and return the count of remaining intervals. A common approach is to sort by start (and end descending on ties) and sweep while tracking the farthest end to detect covered intervals.", "page": 6, "cat": "intervals", "lc": 1288, "en": "LC 1288. Remove Covered Intervals", "cn": "删除被覆盖区间", "id": "lc1288", "sol": {"ap": "按 start 升序 end 降序排,被前一个 end 覆盖则删。", "code": "class Solution:\n    def removeCoveredIntervals(self, intervals):\n        intervals.sort(key=lambda x: (x[0], -x[1]))\n        count = 0; prev_end = 0\n        for s, e in intervals:\n            if e > prev_end:\n                count += 1; prev_end = e\n        return count", "t": "O(n log n)", "s": "O(1)", "fu": ""}}, {"title": "Leetcode 1553. Minimum Number of Days to Eat N Oranges", "level": "Mid-level", "reports": 1, "last": "Mid September, 2024", "desc": "Given n, compute the minimum days to reduce it to 0 when each day you may either eat 1 orange, or—if n is divisible—eat n/2 (leaving n/2) or eat 2*(n/3) (leaving n/3). With n up to 2×10^9 the challenge is to avoid linear DP and use recursion with memoization / divide-and-conquer to explore optimal divide-by-2/3 reductions.", "page": 6, "cat": "binary-search", "lc": 1553, "en": "LC 1553. Minimum Number of Days to Eat N Oranges", "cn": "吃N个橘子最少天数", "id": "lc1553", "sol": {"ap": "记忆化:f(n)=1+min(n%2+f(n//2), n%3+f(n//3))。", "code": "from functools import lru_cache\nclass Solution:\n    def minDays(self, n):\n        @lru_cache(None)\n        def f(n):\n            if n <= 1: return n\n            return 1 + min(n % 2 + f(n // 2), n % 3 + f(n // 3))\n        return f(n)", "t": "O(log²n)", "s": "O(log²n)", "fu": "贪心:尽量除2或除3,余数处-1。"}}, {"title": "Leetcode 3454. Separate Squares II", "level": "Mid-level", "reports": 1, "last": "Early September, 2024", "desc": "Given axis-aligned squares (overlaps counted once), find the minimum y-coordinate of a horizontal line that splits the union area into equal halves. The core challenge is computing the union area below a candidate y (accounting for overlaps) and using its monotonicity to locate the y where that area equals half the total.", "page": 6, "cat": "segment-tree", "lc": 3454, "en": "LC 3454. Separate Squares II", "cn": "分割正方形II", "id": "lc3454", "sol": null}, {"title": "Leetcode 3123. Find Edges in Shortest Paths", "level": "Mid-level", "reports": 1, "last": "Early September, 2024", "desc": "Given an undirected weighted graph, determine for each edge whether it lies on at least one shortest path from node 0 to node n-1. This requires computing shortest distances (e.g., from source and target) and checking for each edge if using it attains the global shortest distance.", "page": 6, "cat": "bfs", "lc": 3123, "en": "LC 3123. Find Edges in Shortest Paths", "cn": "最短路径中的边", "id": "lc3123", "sol": null}, {"title": "Leetcode 3140. Consecutive Available Seats II", "level": "Mid-level", "reports": 1, "last": "Early September, 2024", "desc": "Given a dynamic row of seats with operations that occupy or free individual seats, implement a query that finds and optionally reserves k consecutive available seats (or reports failure). The core challenge is to maintain and query maximal free segments efficiently under many updates, typically solved with interval/segment-tree or ordered-set techniques.", "page": 6, "cat": "intervals", "lc": 3140, "en": "LC 3140. Consecutive Available Seats II", "cn": "连续可用座位II", "id": "lc3140", "sol": null}, {"title": "Leetcode 3217. Delete Nodes From Linked List Present in Array", "level": "Junior", "reports": 1, "last": "Early September, 2024", "desc": "", "page": 6, "cat": "linkedlist", "lc": 3217, "en": "LC 3217. Delete Nodes From Linked List Present in Array", "cn": "删除链表中的节点", "id": "lc3217", "sol": null}, {"title": "Leetcode 1523. Count Odd Numbers in an Interval Range", "level": "Junior", "reports": 1, "last": "Early September, 2024", "desc": "Return the number of odd integers in the inclusive interval [low, high]. The solution is a constant-time arithmetic count (no enumeration), suitable for large bounds up to 10^9.", "page": 6, "cat": "array", "lc": 1523, "en": "LC 1523. Count Odd Numbers in an Interval Range", "cn": "区间内奇数", "id": "lc1523", "sol": null}, {"title": "Design a File Search and Directory Traversal System", "level": "Intern", "reports": 1, "last": "Early September, 2024", "desc": "Design and implement a file search system that can traverse directory structures and locate files based on various criteria. The solution should incorporate object-oriented programming principles, support extensible filtering mechanisms, and be optimized for performance. Consider implementing algorithms like DFS or BFS for traversal, and discuss scalability considerations for adding new search filters and optimizations such as byte-level operations.", "page": 6, "cat": "design", "lc": null, "en": "Design a File Search and Directory Traversal System", "cn": "设计文件搜索与目录遍历", "id": "design-a-file-search-and-directory-trave", "sol": null}, {"title": "Leetcode 1233. Remove Sub-Folders from the Filesystem", "level": "Mid-level", "reports": 1, "last": "Early September, 2024", "desc": "Given a list of absolute folder paths, return only the top-level folders by removing any path that is a subfolder of another. The core challenge is efficiently detecting when one path is a prefix followed by '/' of another (commonly solved with lexicographic sorting and prefix checks or a Trie).", "page": 6, "cat": "trie", "lc": 1233, "en": "LC 1233. Remove Sub-Folders from the Filesystem", "cn": "删除子文件夹", "id": "lc1233", "sol": {"ap": "排序后以「上一个保留+/」开头的是子文件夹,删掉;或建Trie。", "code": "class Solution:\n    def removeSubfolders(self, folder):\n        folder.sort()\n        res = []\n        for f in folder:\n            if not res or not f.startswith(res[-1] + \"/\"):\n                res.append(f)\n        return res", "t": "O(n·L·log n)", "s": "O(n)", "fu": "Trie:遇第一个文件夹结尾就停止下探。"}}, {"title": "String Resolution and Variable Update", "level": "Mid-level", "reports": 1, "last": "Late August, 2024", "desc": "Implement string resolution and variable update functions. Given variable values (e.g. x = 'new', y = '%xworld', z = 'hello'), implement resolveString(string input) to resolve input strings with variable references, and updateVariable(char var, string value) to update variable values.", "page": 6, "cat": "string", "lc": null, "en": "String Resolution and Variable Update", "cn": "字符串解析与变量更新", "id": "string-resolution-and-variable-update", "sol": null}, {"title": "Leetcode 57. Insert Interval", "level": "Mid-level", "reports": 1, "last": "Early August, 2024", "desc": "Insert a given interval into a sorted list of non-overlapping intervals and merge any overlaps so the final list remains sorted and disjoint. The core challenge is to classify intervals as before, overlapping with, or after the new interval and combine overlapping ranges.", "page": 6, "cat": "intervals", "lc": 57, "en": "LC 57. Insert Interval", "cn": "插入区间", "id": "lc57", "sol": {"ap": "已排序线性扫:左不重叠直接加,重叠合并,右直接加。", "code": "class Solution:\n    def insert(self, intervals, newInterval):\n        res = []; i, n = 0, len(intervals)\n        while i < n and intervals[i][1] < newInterval[0]:\n            res.append(intervals[i]); i += 1\n        while i < n and intervals[i][0] <= newInterval[1]:\n            newInterval[0] = min(newInterval[0], intervals[i][0])\n            newInterval[1] = max(newInterval[1], intervals[i][1]); i += 1\n        res.append(newInterval)\n        while i < n:\n            res.append(intervals[i]); i += 1\n        return res", "t": "O(n)", "s": "O(n)", "fu": "多次插入保持高效 → 平衡树/SortedList,单次 O(log n)。"}}, {"title": "Leetcode 920. Number of Music Playlists", "level": "Junior", "reports": 1, "last": "Late July, 2024", "desc": "Count the number of length-goal sequences using n distinct songs such that every song appears at least once and a song can be replayed only after k other songs have been played, returning the result modulo 1e9+7. This is a combinatorics/DP problem (inclusion–exclusion or recurrence) to account for permutations and the cooldown constraint with n ≤ goal ≤ 100.", "page": 6, "cat": "dp", "lc": 920, "en": "LC 920. Number of Music Playlists", "cn": "音乐播放列表数", "id": "lc920", "sol": null}, {"title": "2018. Check if Word Can Be Placed In Crossword", "level": "Mid-level", "reports": 1, "last": "Mid July, 2024", "desc": "", "page": 6, "cat": "array", "lc": null, "en": "2018. Check if Word Can Be Placed In Crossword", "cn": "2018. Check if Word Can Be Placed In Crossword", "id": "2018-check-if-word-can-be-placed-in-cros", "sol": null}, {"title": "Find Top K Chat Contributors", "level": "Mid-level", "reports": 1, "last": "Mid July, 2024", "desc": "Given a Hangout chat log, find the top k contributors, and return the result in reverse order.", "page": 7, "cat": "heap", "lc": null, "en": "Find Top K Chat Contributors", "cn": "找前K聊天贡献者", "id": "find-top-k-chat-contributors", "sol": null}, {"title": "Leetcode 403. Frog Jump", "level": "Mid-level", "reports": 1, "last": "Mid November, 2022", "desc": "Given sorted stone positions and an initial jump of 1, determine whether a frog can reach the last stone when each jump length must be k-1, k, or k+1 from the previous jump. The core challenge is exploring reachable jump sizes per stone under position gaps — typically solved with dynamic programming/DFS using a map/set of stones to reachable jump lengths.", "page": 7, "cat": "dp", "lc": 403, "en": "LC 403. Frog Jump", "cn": "青蛙过河", "id": "lc403", "sol": null}];
